window.REVIEW_V2_CATALOG = {"version":"1002_review_v2_batch_2","themes":[{"id":"daily-life","en":"Daily Life","zh":"日常生活","desc":"Home, errands, small problems, and everyday routines."},{"id":"social-communication","en":"Social & Communication","zh":"社交与沟通","desc":"Friends, requests, misunderstandings, and natural interaction."},{"id":"food-shopping","en":"Food & Shopping","zh":"饮食与购物","desc":"Restaurants, cafés, buying things, payment, and service situations."},{"id":"travel-transport","en":"Travel & Transportation","zh":"旅行与交通","desc":"Trips, stations, airports, directions, hotels, and getting around."},{"id":"plans-time","en":"Plans & Time","zh":"计划与时间","desc":"Schedules, appointments, changing plans, and timing."},{"id":"work-study","en":"Work & Study","zh":"工作与学习","desc":"Problem solving, decisions, teamwork, feedback, and learning."}],"courses":[{"id":"rv2-travel-01","theme":"travel-transport","order":1,"title":"Planning a Weekend Trip","titleZh":"规划周末短途旅行","summary":"Compare transportation and location choices before booking a short trip.","patterns":[{"sentenceId":"s-a2-33","conversationId":"a2-train-or-bus","enHint":"I'm trying to decide between + option A + and + option B.","zhHint":"我正在考虑要选……还是……。","explanation":"Use this when you are genuinely choosing between two alternatives and have not decided yet."},{"sentenceId":"s-a2-38","conversationId":"a2-book-online","enHint":"It would be easier if + subject + past-tense verb.","zhHint":"如果……，会比较容易。","explanation":"Use this to suggest a practical change that would make a situation easier."},{"sentenceId":"s-a1-31","conversationId":"a1-find-pharmacy","enHint":"Is there a + place / thing + nearby?","zhHint":"附近有……吗？","explanation":"A direct everyday pattern for asking whether a place or thing is close to you."},{"sentenceId":"s-b1-17","conversationId":"b1-compare-services","enHint":"We gain + benefit, but we give up + cost / benefit.","zhHint":"我们得到……，但也会牺牲……。","explanation":"Use this to describe a trade-off: one choice gives you something but costs you something else."},{"sentenceId":"s-b1-20","conversationId":"b1-group-priorities","enHint":"What we know is that + fact; what we're assuming is + assumption.","zhHint":"我们确定的是……；我们推测的是……。","explanation":"Use this to separate confirmed information from an assumption before making a decision."}],"lines":[{"en":"My friend and I are planning a short trip this weekend.","zh":"我和朋友正在规划这个周末的短途旅行。","patterns":[]},{"en":"I'm trying to decide between taking the train and renting a car.","zh":"我正在考虑要搭火车还是租车。","patterns":["s-a2-33"]},{"en":"The train is faster, but a car would give us more freedom once we arrive.","zh":"火车比较快，但到了以后，有车会让我们行动更自由。","patterns":[]},{"en":"It would be easier if we stayed near the station.","zh":"如果我们住在车站附近，整个行程会比较轻松。","patterns":["s-a2-38"]},{"en":"Is there a supermarket nearby?","zh":"附近有超市吗？","patterns":["s-a1-31"]},{"en":"We also want a place where we can walk to dinner at night.","zh":"我们也希望住的地方晚上可以直接走路去吃饭。","patterns":[]},{"en":"We gain more flexibility with a car, but we give up some convenience.","zh":"开车会让我们更有弹性，但也会牺牲一些便利性。","patterns":["s-b1-17"]},{"en":"What we know is that the train is faster; what we're assuming is that the hotel will be easy to reach.","zh":"我们确定的是火车比较快；我们推测的是饭店应该很容易到达。","patterns":["s-b1-20"]},{"en":"Before we book anything, we're going to compare the total cost one more time.","zh":"在预订之前，我们会再比较一次全部费用。","patterns":[]},{"en":"Then we'll choose the option that makes the whole weekend easier, not just the first hour of the trip.","zh":"最后我们会选让整个周末更轻松的方案，而不是只看旅程最开始的一个小时。","patterns":[]}]},{"id":"rv2-travel-02","theme":"travel-transport","order":2,"title":"Handling a Gate Change","titleZh":"处理机场登机口临时变更","summary":"Follow a gate change without losing track of the confirmed details.","patterns":[{"sentenceId":"s-a2-36","conversationId":"a2-flight-delay","enHint":"It looks like + subject + has / have been + past participle.","zhHint":"看起来……已经被……了。","explanation":"Use this when visible information suggests that something has changed."},{"sentenceId":"s-b1-4","conversationId":"b1-last-minute-change","enHint":"I didn't realize + fact + until + time / event.","zhHint":"我一直到……才发现……。","explanation":"Use this when you discovered something later than you should have."},{"sentenceId":"s-b1-39","conversationId":"b1-under-impression","enHint":"I was under the impression that + clause.","zhHint":"我原本以为……。","explanation":"A careful way to explain what you believed before receiving corrected information."},{"sentenceId":"s-a1-15","conversationId":"a1-bus-stop","enHint":"Where is the + place?","zhHint":"……在哪里？","explanation":"A basic location question for finding a specific place."},{"sentenceId":"s-a2-2","conversationId":"a2-flight-details","enHint":"Do you know if + clause?","zhHint":"你知道是否……吗？","explanation":"Use this to check information without assuming the answer is yes or no."}],"lines":[{"en":"We got to the airport early, so I thought we had plenty of time.","zh":"我们很早就到了机场，所以我原本以为时间很充裕。","patterns":[]},{"en":"When we reached the gate, the screen showed a different flight.","zh":"走到登机口以后，我们发现屏幕上显示的是另一班飞机。","patterns":[]},{"en":"It looks like our gate has been changed.","zh":"看起来我们的登机口已经被更改了。","patterns":["s-a2-36"]},{"en":"I didn't realize the gate had changed until I checked the airline app.","zh":"我一直到查看航空公司的应用程序，才发现登机口已经变更。","patterns":["s-b1-4"]},{"en":"I was under the impression that we were still boarding at B10.","zh":"我原本以为我们还是在 B10 登机。","patterns":["s-b1-39"]},{"en":"I asked a staff member, \"Where is gate B12?\"","zh":"我问工作人员：「B12 登机口在哪里？」","patterns":["s-a1-15"]},{"en":"I also asked, \"Do you know if the boarding time has changed?\"","zh":"我也问：「你知道登机时间有没有改变吗？」","patterns":["s-a2-2"]},{"en":"He said the time was the same and showed us the fastest way there.","zh":"他说时间没有改变，并告诉我们最快怎么走过去。","patterns":[]},{"en":"We walked quickly, but we didn't need to go through security again.","zh":"我们快步走过去，不过不需要重新通过安检。","patterns":[]},{"en":"In the end, we arrived at the new gate before boarding started.","zh":"最后，我们在开始登机以前就抵达了新的登机口。","patterns":[]}]},{"id":"rv2-daily-01","theme":"daily-life","order":1,"title":"A Leak Under the Kitchen Sink","titleZh":"厨房水槽下方漏水","summary":"Report a small home problem and follow up on the repair time.","patterns":[{"sentenceId":"s-a2-34","conversationId":"a2-about-to-leave","enHint":"I was about to + base verb + when + past event.","zhHint":"我正要……的时候，突然……。","explanation":"Use this when one action was just about to happen and another event interrupted it."},{"sentenceId":"s-a2-25","conversationId":"a2-building-repair","enHint":"There seems to be a problem with + noun.","zhHint":"……似乎有点问题。","explanation":"A neutral way to report a problem before you know exactly what caused it."},{"sentenceId":"s-a1-13","conversationId":"a1-phone-charge","enHint":"I need help with + noun / -ing form.","zhHint":"我需要人帮我处理……。","explanation":"A simple everyday pattern for clearly saying what you need help with."},{"sentenceId":"s-a2-29","conversationId":"a2-ask-update","enHint":"Could you let me know when + clause?","zhHint":"……以后，可以告诉我吗？","explanation":"Use this when you want someone to update you after a future event happens."},{"sentenceId":"s-b1-35","conversationId":"b1-bring-up-noise","enHint":"The reason I brought it up is that + clause.","zhHint":"我之所以提这件事，是因为……。","explanation":"Use this when you want to explain why you decided to mention a problem or concern."}],"lines":[{"en":"I was about to leave for work when I noticed water on the kitchen floor.","zh":"我正要出门上班的时候，突然发现厨房地板上有水。","patterns":["s-a2-34"]},{"en":"At first, I thought I had spilled something.","zh":"一开始，我以为是自己不小心把水打翻了。","patterns":[]},{"en":"Then I saw water dripping from the pipe under the sink.","zh":"后来我看到水槽下面的水管正在滴水。","patterns":[]},{"en":"There seems to be a problem with one of the pipes.","zh":"其中一条水管似乎有点问题。","patterns":["s-a2-25"]},{"en":"I called the building manager and said I needed help with the kitchen sink.","zh":"我打电话给大楼管理人员，说我需要人帮忙处理厨房水槽的问题。","patterns":["s-a1-13"]},{"en":"He asked me to send a photo so he could see where the leak was.","zh":"他请我传一张照片，让他看看漏水的位置。","patterns":[]},{"en":"I asked, \"Could you let me know when the repair person confirms the time?\"","zh":"我问：「维修人员确认时间以后，可以告诉我吗？」","patterns":["s-a2-29"]},{"en":"The reason I brought it up is that the leak is getting worse.","zh":"我之所以提这件事，是因为漏水的情况越来越严重。","patterns":["s-b1-35"]},{"en":"He said someone should be able to come after five tomorrow.","zh":"他说明天五点以后应该会有人可以过来处理。","patterns":[]},{"en":"Until then, I'm keeping a towel under the sink and checking the floor every few hours.","zh":"在那之前，我会在水槽下面放一条毛巾，并且每隔几个小时检查一次地板。","patterns":[]}]},{"id":"rv2-daily-02","theme":"daily-life","order":2,"title":"A Rushed Morning","titleZh":"一个手忙脚乱的早晨","summary":"Deal with a late start, a forgotten item, and a small change of plan before work.","patterns":[{"sentenceId":"s-a1-4","conversationId":"a1-after-work","enHint":"I usually + base verb + after / before + routine time.","zhHint":"我通常会在……以后／以前……。","explanation":"Use this to describe a regular part of your daily routine."},{"sentenceId":"s-a1-14","conversationId":"a1-lost-item","enHint":"I forgot to + base verb.","zhHint":"我忘了要……。","explanation":"Use this when you failed to do something you intended or needed to do."},{"sentenceId":"s-a2-5","conversationId":"a2-ended-up","enHint":"I ended up + -ing form.","zhHint":"最后我还是……了。","explanation":"Use this when the final result was different from the original plan."},{"sentenceId":"s-b1-4","conversationId":"b1-almost-but","enHint":"I didn't realize + clause + until + event / time.","zhHint":"我一直到……才发现……。","explanation":"Use this when you noticed something later than expected."}],"lines":[{"en":"I usually make breakfast before I leave for work.","zh":"我通常会在出门上班以前做早餐。","patterns":["s-a1-4"]},{"en":"This morning, I woke up almost thirty minutes late.","zh":"今天早上，我晚了将近三十分钟才起床。","patterns":[]},{"en":"I forgot to charge my phone last night.","zh":"我昨晚忘了帮手机充电。","patterns":["s-a1-14"]},{"en":"I was going to eat at home, but there wasn't enough time.","zh":"我原本打算在家吃早餐，但时间不够。","patterns":[]},{"en":"I ended up buying coffee and a sandwich near the station.","zh":"最后我还是在车站附近买了咖啡和三明治。","patterns":["s-a2-5"]},{"en":"On the way there, I checked my bag and noticed something was missing.","zh":"在过去的路上，我检查了一下包包，发现少了东西。","patterns":[]},{"en":"I didn't realize I had left my umbrella at home until I was already on the train.","zh":"我一直到已经上了火车，才发现把雨伞留在家里。","patterns":["s-b1-4"]},{"en":"The weather looked fine, so I decided not to go back for it.","zh":"天气看起来还不错，所以我决定不回去拿。","patterns":[]},{"en":"I arrived at work a little later than usual, but I still made it before the first meeting.","zh":"我比平常晚一点到公司，不过还是赶上了第一场会议。","patterns":[]},{"en":"Tomorrow I'm putting my phone and umbrella next to the door before I go to bed.","zh":"明天睡前，我会把手机和雨伞都放到门边。","patterns":[]}]},{"id":"rv2-daily-03","theme":"daily-life","order":3,"title":"Picking Up a Package","titleZh":"领取包裹","summary":"Find the right counter, explain a missing package, and ask for an update.","patterns":[{"sentenceId":"s-a1-9","conversationId":"a1-pickup-package","enHint":"I'm here to + base verb.","zhHint":"我是来……的。","explanation":"Use this to state your purpose when you arrive somewhere."},{"sentenceId":"s-a1-19","conversationId":"a1-pickup-package","enHint":"Is this the right place for + noun / -ing form?","zhHint":"这里是办理……的地方吗？","explanation":"Use this when you want to confirm that you are at the correct counter or location."},{"sentenceId":"s-a1-20","conversationId":"a1-lost-item","enHint":"I'm missing + noun.","zhHint":"我少了／找不到……。","explanation":"Use this to say that something expected is not there."},{"sentenceId":"s-a2-29","conversationId":"a2-ask-update","enHint":"Could you let me know when + clause?","zhHint":"……以后，可以告诉我吗？","explanation":"Use this when you want an update after a future event."},{"sentenceId":"s-b1-42","conversationId":"b1-what-bothers-me","enHint":"What bothers me most is not + noun / clause; it's + noun / clause.","zhHint":"最让我困扰的不是……，而是……。","explanation":"Use this to distinguish the real problem from a less important one."}],"lines":[{"en":"I'm here to pick up a package that arrived yesterday.","zh":"我是来领取昨天送到的包裹。","patterns":["s-a1-9"]},{"en":"The message told me to go to the service counter on the first floor.","zh":"通知要我去一楼的服务柜台。","patterns":[]},{"en":"I asked, \"Is this the right place for package pickup?\"","zh":"我问：「这里是领取包裹的地方吗？」","patterns":["s-a1-19"]},{"en":"The staff member checked my name and phone number.","zh":"工作人员确认了我的姓名和电话号码。","patterns":[]},{"en":"After looking for a few minutes, he said the package was not on the shelf.","zh":"找了几分钟以后，他说架子上没有那个包裹。","patterns":[]},{"en":"I told him, \"I'm missing one package from yesterday's delivery.\"","zh":"我告诉他：「我少了一个昨天送到的包裹。」","patterns":["s-a1-20"]},{"en":"He said he would check with the delivery team.","zh":"他说他会跟配送人员确认。","patterns":[]},{"en":"I asked, \"Could you let me know when you find out where it is?\"","zh":"我问：「你们确认包裹在哪里以后，可以告诉我吗？」","patterns":["s-a2-29"]},{"en":"What bothers me most is not waiting another day; it's not knowing where the package is.","zh":"最让我困扰的不是多等一天，而是不知道包裹到底在哪里。","patterns":["s-b1-42"]},{"en":"He took my number and promised to contact me as soon as he had an answer.","zh":"他记下我的电话号码，并答应一有结果就联系我。","patterns":[]}]},{"id":"rv2-social-01","theme":"social-communication","order":1,"title":"Meeting a Friend When You're Running Late","titleZh":"迟到时和朋友会合","summary":"Update a friend, confirm the meeting point, and adjust the plan without making the situation awkward.","patterns":[{"sentenceId":"s-a1-25","conversationId":"a1-on-the-way","enHint":"I'm on my way to + place.","zhHint":"我正在去……的路上。","explanation":"Use this to tell someone that you have already started traveling to the meeting place."},{"sentenceId":"s-a1-38","conversationId":"a1-meet-station","enHint":"I'll meet you in front of + place.","zhHint":"我会在……前面跟你会合。","explanation":"Use this to set a clear meeting point."},{"sentenceId":"s-a2-41","conversationId":"a2-running-late","enHint":"I'm running a little late, but + clause.","zhHint":"我会晚一点，不过……。","explanation":"Use this to give a late-arrival update while also reassuring the other person."},{"sentenceId":"s-a2-45","conversationId":"a2-move-time","enHint":"Could we move + plan + to + time + instead?","zhHint":"我们可以把……改到……吗？","explanation":"Use this to propose a new time for an existing plan."},{"sentenceId":"s-b1-32","conversationId":"b1-too-tired","enHint":"It's not that + clause; it's just that + clause.","zhHint":"不是因为……，只是因为……。","explanation":"Use this to correct a possible misunderstanding about your reason."}],"lines":[{"en":"I was supposed to meet my friend downtown at six thirty.","zh":"我原本应该六点半在市中心和朋友见面。","patterns":[]},{"en":"At six fifteen, I was still finishing something at work.","zh":"六点十五分的时候，我还在公司处理事情。","patterns":[]},{"en":"I sent him a message saying, \"I'm running a little late, but I'm leaving now.\"","zh":"我传讯息告诉他：「我会晚一点，不过我现在就要出发了。」","patterns":["s-a2-41"]},{"en":"A few minutes later, I told him, \"I'm on my way to the station.\"","zh":"几分钟后，我告诉他：「我正在去车站的路上。」","patterns":["s-a1-25"]},{"en":"He asked whether we should still meet at the same place.","zh":"他问我们是不是还要在原本的地方见面。","patterns":[]},{"en":"I said, \"I'll meet you in front of the bookstore.\"","zh":"我说：「我会在书店前面跟你会合。」","patterns":["s-a1-38"]},{"en":"Then I asked, \"Could we move dinner to seven instead?\"","zh":"然后我问：「我们可以把晚餐改到七点吗？」","patterns":["s-a2-45"]},{"en":"He said that was fine and decided to walk around first.","zh":"他说没问题，并决定先在附近逛一下。","patterns":[]},{"en":"I explained, \"It's not that I forgot our plan; it's just that work took longer than expected.\"","zh":"我解释：「不是因为我忘了我们的约定，只是工作比预期花了更久。」","patterns":["s-b1-32"]},{"en":"When I finally arrived, we were both relaxed because the plan had already been adjusted clearly.","zh":"等我终于抵达时，因为我们已经把安排讲清楚了，所以两个人都很轻松。","patterns":[]}]},{"id":"rv2-social-02","theme":"social-communication","order":2,"title":"Clearing Up a Text Message","titleZh":"澄清文字讯息造成的误会","summary":"Check what someone meant before a small misunderstanding becomes a bigger one.","patterns":[{"sentenceId":"s-a1-23","conversationId":"a1-clarify-entrance","enHint":"Do you mean + noun / clause?","zhHint":"你的意思是……吗？","explanation":"Use this to check the meaning of something you just heard or read."},{"sentenceId":"s-a2-23","conversationId":"a2-confirm-heard","enHint":"Just to make sure, did you say + clause?","zhHint":"确认一下，你刚刚是说……吗？","explanation":"Use this when you want to confirm the exact information before responding."},{"sentenceId":"s-b1-2","conversationId":"b1-misunderstanding","enHint":"What I mean is that + clause.","zhHint":"我的意思是……。","explanation":"Use this to restate your intended meaning more clearly."},{"sentenceId":"s-b1-39","conversationId":"b1-under-impression","enHint":"I was under the impression that + clause.","zhHint":"我原本以为……。","explanation":"Use this to explain a belief that may have been incorrect."},{"sentenceId":"s-b1-19","conversationId":"b1-ask-context","enHint":"Correct me if I'm wrong, but + clause.","zhHint":"如果我理解错了请纠正我，不过……。","explanation":"Use this to present your current understanding while inviting correction."}],"lines":[{"en":"A friend sent me a short message that sounded more serious than usual.","zh":"朋友传给我一则很短的讯息，语气听起来比平常严肃。","patterns":[]},{"en":"At first I wasn't sure whether he was annoyed with me.","zh":"一开始，我不确定他是不是对我有点不满。","patterns":[]},{"en":"I replied, \"Do you mean you're upset about what happened yesterday?\"","zh":"我回复：「你的意思是你在意昨天发生的事情吗？」","patterns":["s-a1-23"]},{"en":"He said no, so I asked, \"Just to make sure, did you say you wanted to talk later?\"","zh":"他说不是，所以我又问：「确认一下，你刚刚是说想晚一点再聊吗？」","patterns":["s-a2-23"]},{"en":"He told me that he had only been busy and had written the message quickly.","zh":"他告诉我，他只是很忙，所以讯息写得很快。","patterns":[]},{"en":"I said, \"I was under the impression that something was wrong.\"","zh":"我说：「我原本以为出了什么问题。」","patterns":["s-b1-39"]},{"en":"Then I added, \"Correct me if I'm wrong, but I thought the message sounded a little cold.\"","zh":"接着我补充：「如果我理解错了请纠正我，不过我觉得那则讯息听起来有点冷淡。」","patterns":["s-b1-19"]},{"en":"He laughed and said he could see why I had read it that way.","zh":"他笑了，说他能理解为什么我会那样解读。","patterns":[]},{"en":"He explained, \"What I mean is that I want to talk when I have more time, not avoid you.\"","zh":"他解释：「我的意思是，我想等有更多时间的时候再好好聊，不是在躲你。」","patterns":["s-b1-2"]},{"en":"The misunderstanding disappeared once we checked the meaning instead of guessing.","zh":"我们确认彼此的意思，而不是继续猜测以后，误会很快就消失了。","patterns":[]}]},{"id":"rv2-social-03","theme":"social-communication","order":3,"title":"Visiting a Friend's New Place","titleZh":"拜访朋友的新住处","summary":"Ask where things go, check what is okay, and make yourself easy to host.","patterns":[{"sentenceId":"s-a1-43","conversationId":"a1-where-put","enHint":"Where should I put + noun?","zhHint":"我应该把……放在哪里？","explanation":"Use this when you are carrying something and want to know the right place for it."},{"sentenceId":"s-a1-45","conversationId":"a1-is-it-okay","enHint":"Is it okay if I + base verb?","zhHint":"如果我……可以吗？","explanation":"Use this to ask permission in a casual everyday situation."},{"sentenceId":"s-a2-32","conversationId":"a2-asking-help","enHint":"Would you mind + -ing form?","zhHint":"你介意……吗？","explanation":"Use this for a polite small request."},{"sentenceId":"s-a2-35","conversationId":"a2-last-time-cafe","enHint":"The last time I + past verb, + clause.","zhHint":"上次我……的时候，……。","explanation":"Use this to connect the current situation with a previous experience."},{"sentenceId":"s-b1-40","conversationId":"b1-dont-mind-as-long","enHint":"I don't mind + -ing / noun + as long as + clause.","zhHint":"只要……，我不介意……。","explanation":"Use this to accept something while setting one simple condition."}],"lines":[{"en":"A friend recently moved into a new apartment, and I went over for dinner.","zh":"朋友最近搬进新公寓，我去他家吃晚餐。","patterns":[]},{"en":"When I walked in, I was carrying a bottle of juice and a small bag.","zh":"进门的时候，我手上拿着一瓶果汁和一个小袋子。","patterns":[]},{"en":"I asked, \"Where should I put the drinks?\"","zh":"我问：「饮料应该放在哪里？」","patterns":["s-a1-43"]},{"en":"Then I asked, \"Is it okay if I leave my bag by the door?\"","zh":"然后我问：「我把包包放在门边可以吗？」","patterns":["s-a1-45"]},{"en":"He said yes and showed me around the apartment.","zh":"他说可以，并带我看了一下新家。","patterns":[]},{"en":"The last time I visited him, he was still living with roommates.","zh":"上次我去找他的时候，他还和室友一起住。","patterns":["s-a2-35"]},{"en":"Now he finally has a small place of his own.","zh":"现在他终于有了自己的小空间。","patterns":[]},{"en":"Before dinner, he asked, \"Would you mind helping me move this chair?\"","zh":"吃饭以前，他问：「你介意帮我移动一下这张椅子吗？」","patterns":["s-a2-32"]},{"en":"I told him, \"I don't mind helping as long as you tell me where you want it.\"","zh":"我告诉他：「只要你告诉我要放哪里，我不介意帮忙。」","patterns":["s-b1-40"]},{"en":"A few minutes later, everything was ready and we could finally sit down to eat.","zh":"几分钟后，一切都准备好了，我们终于可以坐下来吃饭。","patterns":[]}]},{"id":"rv2-food-01","theme":"food-shopping","order":1,"title":"Ordering Lunch the Way You Want It","titleZh":"把午餐点成自己想要的样子","summary":"Order naturally, make a small change, and explain what you actually want.","patterns":[{"sentenceId":"s-a1-2","conversationId":"a1-food-meals","enHint":"Could I have + noun, please?","zhHint":"可以给我……吗？","explanation":"A standard polite pattern for ordering or asking for something."},{"sentenceId":"s-a1-36","conversationId":"a1-no-onions","enHint":"Can I get + food + without + ingredient?","zhHint":"我可以点……不要……吗？","explanation":"Use this to remove an ingredient from a food order."},{"sentenceId":"s-a1-37","conversationId":"a1-too-spicy","enHint":"This is a little too + adjective + for me.","zhHint":"这个对我来说有点太……了。","explanation":"Use this to say that something is beyond your preferred level."},{"sentenceId":"s-a2-30","conversationId":"a2-needed-result","enHint":"What I need is + noun, not + noun.","zhHint":"我需要的是……，不是……。","explanation":"Use this to clearly distinguish the result you need from the one being offered."},{"sentenceId":"s-b1-43","conversationId":"b1-rather-than","enHint":"I'd rather + base verb + than + base verb.","zhHint":"我宁愿……也不要……。","explanation":"Use this to express a clear preference between two actions."}],"lines":[{"en":"I went to a small restaurant near work for lunch.","zh":"我中午去了公司附近的一家小餐厅。","patterns":[]},{"en":"I said, \"Could I have the chicken rice, please?\"","zh":"我说：「可以给我一份鸡肉饭吗？」","patterns":["s-a1-2"]},{"en":"I also asked, \"Can I get it without onions?\"","zh":"我也问：「可以不要洋葱吗？」","patterns":["s-a1-36"]},{"en":"The staff told me the sauce was fairly spicy.","zh":"工作人员告诉我酱汁会比较辣。","patterns":[]},{"en":"I said, \"This is a little too spicy for me,\" after trying a small sample.","zh":"试了一小口以后，我说：「这个对我来说有点太辣了。」","patterns":["s-a1-37"]},{"en":"They offered to put the sauce on the side instead.","zh":"他们提议把酱汁另外装。","patterns":[]},{"en":"I explained, \"What I need is less sauce, not a completely different dish.\"","zh":"我解释：「我需要的是少一点酱汁，不是换成完全不同的餐点。」","patterns":["s-a2-30"]},{"en":"That was easy for them to change.","zh":"这样对他们来说很好调整。","patterns":[]},{"en":"I'd rather make one small change than order something I don't really want.","zh":"我宁愿做一个小调整，也不要点一个自己其实不想吃的东西。","patterns":["s-b1-43"]},{"en":"A few minutes later, my lunch came exactly the way I wanted it.","zh":"几分钟后，我的午餐就按照我想要的方式送来了。","patterns":[]}]},{"id":"rv2-food-02","theme":"food-shopping","order":2,"title":"Fixing a Checkout Problem","titleZh":"处理结账时的小问题","summary":"Check a charge, explain the problem, and ask for the correct result without sounding aggressive.","patterns":[{"sentenceId":"s-a1-16","conversationId":"a1-asking-receipt","enHint":"How much is + noun?","zhHint":"……多少钱？","explanation":"Use this to check a price directly."},{"sentenceId":"s-a1-32","conversationId":"a1-payment-method","enHint":"Do you take + payment method?","zhHint":"你们收……吗？","explanation":"Use this to ask whether a store accepts a payment method."},{"sentenceId":"s-a2-25","conversationId":"a2-soft-problem","enHint":"There seems to be a problem with + noun.","zhHint":"……似乎有点问题。","explanation":"A neutral way to point out a problem without immediately blaming someone."},{"sentenceId":"s-a2-13","conversationId":"a2-return-item","enHint":"I'd like to make sure + clause.","zhHint":"我想确认一下……。","explanation":"Use this when you want to verify information before taking the next step."},{"sentenceId":"s-b1-42","conversationId":"b1-what-bothers-me","enHint":"What bothers me most is not + noun / clause; it's + noun / clause.","zhHint":"最让我困扰的不是……，而是……。","explanation":"Use this to identify the real issue behind a complaint."}],"lines":[{"en":"I bought a few things at a small shop after work.","zh":"下班后，我在一家小店买了几样东西。","patterns":[]},{"en":"Before paying, I asked, \"How much is this notebook?\"","zh":"付款以前，我问：「这本笔记本多少钱？」","patterns":["s-a1-16"]},{"en":"I also asked, \"Do you take mobile payment?\"","zh":"我也问：「你们收行动支付吗？」","patterns":["s-a1-32"]},{"en":"After I paid, the total looked higher than I expected.","zh":"付款以后，总金额看起来比我预期的高。","patterns":[]},{"en":"There seems to be a problem with one of the charges.","zh":"其中一笔收费似乎有点问题。","patterns":["s-a2-25"]},{"en":"I checked the receipt and saw the same item listed twice.","zh":"我检查收据，发现同一个商品被列了两次。","patterns":[]},{"en":"I said, \"I'd like to make sure I wasn't charged twice for the same thing.\"","zh":"我说：「我想确认一下，我是不是同一个商品被收了两次钱。」","patterns":["s-a2-13"]},{"en":"The cashier checked the system and immediately saw the mistake.","zh":"店员检查系统后，马上看到了错误。","patterns":[]},{"en":"What bothers me most is not the small amount of money; it's leaving without knowing whether the total is correct.","zh":"最让我困扰的不是那一点金额，而是不确定总金额到底对不对就离开。","patterns":["s-b1-42"]},{"en":"The cashier refunded the extra charge, and the problem was solved in a few minutes.","zh":"店员退回了多收的钱，几分钟内问题就解决了。","patterns":[]}]},{"id":"rv2-food-03","theme":"food-shopping","order":3,"title":"Choosing Where to Eat","titleZh":"决定要去哪里吃饭","summary":"Compare preferences without turning a simple dinner choice into a long argument.","patterns":[{"sentenceId":"s-a1-8","conversationId":"a1-food-meals","enHint":"I prefer + noun + because + clause.","zhHint":"我比较喜欢……，因为……。","explanation":"Use this for a simple preference with one reason."},{"sentenceId":"s-a2-20","conversationId":"a2-not-in-mood","enHint":"I'd prefer + noun / to-infinitive + because + clause.","zhHint":"我会比较想……，因为……。","explanation":"A slightly softer, more flexible way to explain a preference."},{"sentenceId":"s-a2-37","conversationId":"a2-friday-saturday","enHint":"Either + option A + or + option B + works for me.","zhHint":"……或……我都可以。","explanation":"Use this when two different options are both acceptable."},{"sentenceId":"s-b1-40","conversationId":"b1-dont-mind-as-long","enHint":"I don't mind + option + as long as + clause.","zhHint":"只要……，我不介意……。","explanation":"Use this to accept a choice while stating one condition."},{"sentenceId":"s-b1-45","conversationId":"b1-can-see-why","enHint":"I get why + clause, but + clause.","zhHint":"我理解为什么……，不过……。","explanation":"Use this to acknowledge someone else's preference before giving a different view."}],"lines":[{"en":"Three of us were trying to decide where to eat after work.","zh":"我们三个人下班后正在决定要去哪里吃饭。","patterns":[]},{"en":"I said, \"I prefer the noodle place because it's quieter.\"","zh":"我说：「我比较喜欢那家面店，因为那里比较安静。」","patterns":["s-a1-8"]},{"en":"One friend wanted to try a popular restaurant that had just opened.","zh":"一个朋友想去试一家刚开幕的热门餐厅。","patterns":[]},{"en":"Another friend said either the noodle place or the café worked for him.","zh":"另一个朋友说面店或咖啡厅他都可以。","patterns":["s-a2-37"]},{"en":"I explained, \"I'd prefer somewhere close because I have to leave early tonight.\"","zh":"我解释：「我会比较想去近一点的地方，因为我今晚得早点离开。」","patterns":["s-a2-20"]},{"en":"The popular restaurant was farther away and usually had a long line.","zh":"那家热门餐厅比较远，而且通常要排很久。","patterns":[]},{"en":"My friend said he didn't mind waiting as long as the food was worth it.","zh":"我朋友说只要食物值得，他不介意等。","patterns":["s-b1-40"]},{"en":"I told him, \"I get why you want to try it, but tonight may not be the best time.\"","zh":"我告诉他：「我理解你为什么想试，不过今晚可能不是最适合的时候。」","patterns":["s-b1-45"]},{"en":"In the end, we chose the closer restaurant and saved the new place for the weekend.","zh":"最后我们选了比较近的餐厅，把新店留到周末再去。","patterns":[]},{"en":"The decision became easy once everyone explained what actually mattered to them.","zh":"每个人都说清楚自己真正重视的事情以后，决定就变得很简单。","patterns":[]}]},{"id":"rv2-travel-03","theme":"travel-transport","order":3,"title":"A Small Hotel Check-In Problem","titleZh":"饭店入住时的小问题","summary":"Confirm the right desk, check requirements, and politely correct information at check-in.","patterns":[{"sentenceId":"s-a1-19","conversationId":"a1-clarify-entrance","enHint":"Is this the right place for + noun / -ing form?","zhHint":"这里是办理……的地方吗？","explanation":"Use this to confirm that you have reached the correct counter or location."},{"sentenceId":"s-a2-9","conversationId":"a2-hotel-checkin","enHint":"Would it be possible to + base verb?","zhHint":"可以……吗？","explanation":"Use this for a polite request when you are asking for an exception or change."},{"sentenceId":"s-a2-18","conversationId":"a2-rental-rules","enHint":"Do I need to + base verb + before + noun / -ing form?","zhHint":"在……以前，我需要先……吗？","explanation":"Use this to check whether there is a required step before another action."},{"sentenceId":"s-a2-19","conversationId":"a2-hotel-checkin","enHint":"I thought + subject + was supposed to + base verb.","zhHint":"我原本以为……应该会……。","explanation":"Use this when reality is different from what you expected."},{"sentenceId":"s-b1-39","conversationId":"b1-under-impression","enHint":"I was under the impression that + clause.","zhHint":"我原本以为……。","explanation":"Use this to explain a previous understanding in a careful, non-confrontational way."}],"lines":[{"en":"I arrived at my hotel a little before the official check-in time.","zh":"我比饭店正式入住时间早一点抵达。","patterns":[]},{"en":"The lobby was busy, and there were two different counters.","zh":"大厅很忙，而且有两个不同的柜台。","patterns":[]},{"en":"I asked, \"Is this the right place for check-in?\"","zh":"我问：「这里是办理入住的地方吗？」","patterns":["s-a1-19"]},{"en":"The staff member checked my reservation and found my name.","zh":"工作人员查看了我的预订，并找到了我的名字。","patterns":[]},{"en":"I asked, \"Would it be possible to check in a little early?\"","zh":"我问：「可以稍微提早一点入住吗？」","patterns":["s-a2-9"]},{"en":"She said the room was ready, but I still needed to complete one form.","zh":"她说房间已经准备好了，不过我还是需要填写一份表格。","patterns":[]},{"en":"I asked, \"Do I need to show my passport before signing this?\"","zh":"我问：「签这份表格以前，我需要先出示护照吗？」","patterns":["s-a2-18"]},{"en":"Then I noticed the room type on the form was different from my booking.","zh":"然后我发现表格上的房型和我预订的不一样。","patterns":[]},{"en":"I said, \"I thought my reservation was supposed to include a double room.\"","zh":"我说：「我原本以为我的预订应该会包含一间双人房。」","patterns":["s-a2-19"]},{"en":"I added, \"I was under the impression that the room type had already been confirmed online.\"","zh":"我补充：「我原本以为房型已经在线上确认好了。」","patterns":["s-b1-39"]}]},{"id":"rv2-plans-01","theme":"plans-time","order":1,"title":"Rescheduling an Appointment","titleZh":"重新安排预约时间","summary":"Move an appointment while keeping the alternatives and final time clear.","patterns":[{"sentenceId":"s-a1-28","conversationId":"a1-confirm-detail","enHint":"So, it's + detail, right?","zhHint":"所以是……，对吗？","explanation":"Use this to confirm one specific detail after making an arrangement."},{"sentenceId":"s-a2-9","conversationId":"a2-make-appointment","enHint":"Would it be possible to + base verb?","zhHint":"可以……吗？","explanation":"Use this for a polite request to change an existing arrangement."},{"sentenceId":"s-a2-45","conversationId":"a2-move-time","enHint":"Could we move + plan + to + time + instead?","zhHint":"我们可以把……改到……吗？","explanation":"Use this when proposing a specific new time."},{"sentenceId":"s-a2-37","conversationId":"a2-friday-saturday","enHint":"Either + option A + or + option B + works for me.","zhHint":"……或……我都可以。","explanation":"Use this when more than one time works for you."},{"sentenceId":"s-b1-24","conversationId":"b1-conditional-agreement","enHint":"I'm open to + noun / -ing form, provided that + clause.","zhHint":"只要……，我可以接受……。","explanation":"Use this to agree to an option while keeping one condition."}],"lines":[{"en":"I had an appointment for Thursday afternoon, but a work meeting was added at the same time.","zh":"我原本星期四下午有预约，不过工作临时增加了一场同时间的会议。","patterns":[]},{"en":"I called the office before the appointment day.","zh":"我在预约日期以前先打电话给对方。","patterns":[]},{"en":"I asked, \"Would it be possible to change my appointment?\"","zh":"我问：「可以更改我的预约吗？」","patterns":["s-a2-9"]},{"en":"The staff member offered Friday at four or next Monday at ten.","zh":"工作人员提供星期五四点或下星期一十点两个时间。","patterns":[]},{"en":"I said, \"Either Friday afternoon or Monday morning works for me.\"","zh":"我说：「星期五下午或星期一早上我都可以。」","patterns":["s-a2-37"]},{"en":"Then I asked, \"Could we move the appointment to Friday at four instead?\"","zh":"然后我问：「我们可以把预约改到星期五四点吗？」","patterns":["s-a2-45"]},{"en":"She said that time was still available.","zh":"她说那个时间还有空位。","patterns":[]},{"en":"I told her, \"I'm open to Friday, provided that the appointment can start on time.\"","zh":"我告诉她：「只要可以准时开始，我可以接受星期五。」","patterns":["s-b1-24"]},{"en":"Before hanging up, I asked, \"So, it's Friday at four, right?\"","zh":"挂电话以前，我问：「所以是星期五四点，对吗？」","patterns":["s-a1-28"]},{"en":"She confirmed it, and I added the new time to my calendar immediately.","zh":"她确认以后，我马上把新的时间加进日历。","patterns":[]}]},{"id":"rv2-plans-02","theme":"plans-time","order":2,"title":"Changing Dinner Plans","titleZh":"更改晚餐计划","summary":"Explain why a plan changed and offer a practical backup instead of disappearing at the last minute.","patterns":[{"sentenceId":"s-a1-26","conversationId":"a1-simple-reason","enHint":"I can't + base verb + because + clause.","zhHint":"我不能……，因为……。","explanation":"Use this for a simple direct reason."},{"sentenceId":"s-a1-30","conversationId":"a1-arrival-followup","enHint":"I'll + base verb + when I get there.","zhHint":"我到了以后会……。","explanation":"Use this to promise a simple action after arrival."},{"sentenceId":"s-a2-22","conversationId":"a2-backup-plan","enHint":"If that doesn't work, we can + base verb.","zhHint":"如果那样不行，我们可以……。","explanation":"Use this to offer a backup option."},{"sentenceId":"s-a2-24","conversationId":"a2-explain-change","enHint":"I was going to + base verb, but + clause.","zhHint":"我原本要……，不过……。","explanation":"Use this to explain a change from the original plan."},{"sentenceId":"s-b1-34","conversationId":"b1-rain-trip","enHint":"Even if + clause, I'd still + base verb.","zhHint":"即使……，我还是会……。","explanation":"Use this to say that one problem will not completely change your intention."}],"lines":[{"en":"I had dinner plans with two friends after work.","zh":"我下班后原本和两个朋友约好吃晚餐。","patterns":[]},{"en":"I was going to leave at six, but a customer called just before I finished.","zh":"我原本六点要离开，不过快结束工作以前有客户打电话来。","patterns":["s-a2-24"]},{"en":"I messaged my friends and said, \"I can't leave yet because I need to finish this call.\"","zh":"我传讯息给朋友说：「我现在还不能离开，因为我得先结束这通电话。」","patterns":["s-a1-26"]},{"en":"They said they could wait for a while.","zh":"他们说可以先等一下。","patterns":[]},{"en":"I told them, \"If that doesn't work, we can meet somewhere closer to my office.\"","zh":"我告诉他们：「如果那样不行，我们可以改在离我公司近一点的地方见面。」","patterns":["s-a2-22"]},{"en":"One friend found a restaurant that was only five minutes away.","zh":"一个朋友找到一家距离只有五分钟的餐厅。","patterns":[]},{"en":"I said, \"Even if I finish a little late, I'd still like to join you.\"","zh":"我说：「即使我晚一点结束，我还是想过去跟你们会合。」","patterns":["s-b1-34"]},{"en":"So they changed the restaurant instead of canceling dinner.","zh":"所以他们换了餐厅，而不是取消晚餐。","patterns":[]},{"en":"I told them, \"I'll message you when I get there.\"","zh":"我告诉他们：「我到了以后会传讯息给你们。」","patterns":["s-a1-30"]},{"en":"The plan changed, but everyone still knew what was happening.","zh":"计划虽然变了，不过每个人都清楚现在的安排。","patterns":[]}]},{"id":"rv2-plans-03","theme":"plans-time","order":3,"title":"Checking a Weekend Event","titleZh":"确认周末活动资讯","summary":"Confirm time, weather rules, and backup options before leaving home.","patterns":[{"sentenceId":"s-a1-3","conversationId":"a1-opening-hours","enHint":"What time does + event + start?","zhHint":"……几点开始？","explanation":"Use this to ask for the starting time of an event or activity."},{"sentenceId":"s-a2-2","conversationId":"a2-flight-details","enHint":"Do you know if + clause?","zhHint":"你知道是否……吗？","explanation":"Use this to check information without assuming the answer."},{"sentenceId":"s-a2-27","conversationId":"a2-backup-plan","enHint":"In case + clause, we could + base verb.","zhHint":"万一……，我们可以……。","explanation":"Use this to prepare a backup plan before a possible problem occurs."},{"sentenceId":"s-a2-29","conversationId":"a2-ask-update","enHint":"Could you let me know when + clause?","zhHint":"……以后，可以告诉我吗？","explanation":"Use this when you want an update after something is confirmed."},{"sentenceId":"s-b1-16","conversationId":"b1-flag-uncertainty","enHint":"Based on what we know so far, + clause.","zhHint":"根据目前知道的资讯，……。","explanation":"Use this to make a careful conclusion using the information currently available."}],"lines":[{"en":"A friend sent me information about an outdoor event this weekend.","zh":"朋友传给我一个这个周末户外活动的资讯。","patterns":[]},{"en":"The website had the location, but some details were not very clear.","zh":"网站上有地点，不过有些细节不是很清楚。","patterns":[]},{"en":"I asked, \"What time does the event start?\"","zh":"我问：「活动几点开始？」","patterns":["s-a1-3"]},{"en":"I also asked, \"Do you know if it will still happen if it rains?\"","zh":"我也问：「你知道如果下雨活动还会不会举行吗？」","patterns":["s-a2-2"]},{"en":"My friend wasn't sure, so we checked the official page.","zh":"我朋友不确定，所以我们查看了官方网站。","patterns":[]},{"en":"In case the weather gets worse, we could visit the indoor market nearby instead.","zh":"万一天气变差，我们可以改去附近的室内市场。","patterns":["s-a2-27"]},{"en":"The organizer said a final weather decision would be posted Saturday morning.","zh":"主办单位说星期六早上会公布最后的天气决定。","patterns":[]},{"en":"I asked my friend, \"Could you let me know when they post the update?\"","zh":"我问朋友：「他们发布更新以后，可以告诉我吗？」","patterns":["s-a2-29"]},{"en":"Based on what we know so far, the event is still going ahead.","zh":"根据目前知道的资讯，活动还是会照常举行。","patterns":["s-b1-16"]},{"en":"We'll check one more time before leaving home instead of guessing.","zh":"我们出门以前会再确认一次，而不是自己猜。","patterns":[]}]},{"id":"rv2-work-01","theme":"work-study","order":1,"title":"A Report That Needs One More Day","titleZh":"需要多一天完成的报告","summary":"Explain a delay early, identify uncertain information, and define the next action.","patterns":[{"sentenceId":"s-a2-10","conversationId":"a2-change-shift","enHint":"I'm supposed to + base verb, but + clause.","zhHint":"我本来应该要……，不过……。","explanation":"Use this when an expected responsibility conflicts with reality."},{"sentenceId":"s-a2-16","conversationId":"a2-late-arrival","enHint":"I got delayed because + clause.","zhHint":"我因为……耽误了一下。","explanation":"Use this to explain the reason for a delay."},{"sentenceId":"s-a2-29","conversationId":"a2-ask-update","enHint":"Could you let me know when + clause?","zhHint":"……以后，可以告诉我吗？","explanation":"Use this to request an update that affects your next step."},{"sentenceId":"s-b1-25","conversationId":"b1-flag-uncertainty","enHint":"The part I'm not sure about is + noun / clause.","zhHint":"我不确定的部分是……。","explanation":"Use this to identify one uncertain point instead of treating everything as unclear."},{"sentenceId":"s-b1-30","conversationId":"b1-next-action","enHint":"The next step is to + base verb + so that + clause.","zhHint":"下一步是……，这样……。","explanation":"Use this to define a concrete action and its purpose."}],"lines":[{"en":"I'm supposed to finish a report today, but one section still has incomplete data.","zh":"我本来应该今天完成报告，不过其中一个部分的资料还不完整。","patterns":["s-a2-10"]},{"en":"I got delayed because two numbers in the spreadsheet didn't match the source file.","zh":"我因为试算表里的两个数字和原始档案对不上而耽误了一下。","patterns":["s-a2-16"]},{"en":"I don't want to submit the report while I'm still unsure about those figures.","zh":"我不想在还不确定那些数字的时候就送出报告。","patterns":[]},{"en":"The part I'm not sure about is whether the latest sales data includes yesterday's orders.","zh":"我不确定的部分是最新的销售资料有没有包含昨天的订单。","patterns":["s-b1-25"]},{"en":"I sent a message to the coworker who owns that data.","zh":"我传讯息给负责那些资料的同事。","patterns":[]},{"en":"I asked, \"Could you let me know when you confirm which file is current?\"","zh":"我问：「你确认哪一个档案是最新版本以后，可以告诉我吗？」","patterns":["s-a2-29"]},{"en":"While I wait, I'm checking the rest of the report.","zh":"等待的时候，我正在检查报告的其他部分。","patterns":[]},{"en":"The next step is to correct the numbers so that I can send a clean version tomorrow morning.","zh":"下一步是把数字修正好，这样我明天早上就能送出完整版本。","patterns":["s-b1-30"]},{"en":"I also told my manager about the delay before the end of the day.","zh":"我也在今天结束以前先告诉主管会延迟。","patterns":[]},{"en":"One extra day is easier to manage than fixing a wrong report after it has already been sent.","zh":"多花一天处理，比错误报告送出以后再修正容易得多。","patterns":[]}]},{"id":"rv2-work-02","theme":"work-study","order":2,"title":"Turning Different Opinions into a Decision","titleZh":"把不同意见变成一个决定","summary":"Compare choices using shared criteria instead of repeating personal preferences.","patterns":[{"sentenceId":"s-a2-33","conversationId":"a2-train-or-bus","enHint":"I'm trying to decide between + option A + and + option B.","zhHint":"我正在考虑要选……还是……。","explanation":"Use this when a decision has been narrowed down to two choices."},{"sentenceId":"s-b1-17","conversationId":"b1-compare-services","enHint":"We gain + benefit, but we give up + cost / benefit.","zhHint":"我们得到……，但也会牺牲……。","explanation":"Use this to describe a trade-off clearly."},{"sentenceId":"s-b1-22","conversationId":"b1-group-priorities","enHint":"What would make us choose + option A + over + option B?","zhHint":"什么条件会让我们选择……而不是……？","explanation":"Use this to identify the decision rule instead of only discussing preferences."},{"sentenceId":"s-b1-27","conversationId":"b1-prioritize-one","enHint":"If we can only fix one thing first, I'd prioritize + noun.","zhHint":"如果只能先处理一件事，我会优先……。","explanation":"Use this to select one priority when time or resources are limited."},{"sentenceId":"s-b1-29","conversationId":"b1-check-alignment","enHint":"Before we move on, are we all clear on + noun?","zhHint":"继续之前，我们都清楚……了吗？","explanation":"Use this to confirm shared understanding before ending a discussion."}],"lines":[{"en":"Our team had to choose between two services for a new project.","zh":"我们的团队需要在两个服务方案之间做选择。","patterns":[]},{"en":"I'm trying to decide between the cheaper option and the more reliable one.","zh":"我正在考虑要选比较便宜的方案，还是比较可靠的方案。","patterns":["s-a2-33"]},{"en":"Some people focused on price, while others cared more about support.","zh":"有些人重视价格，其他人则更在意支援服务。","patterns":[]},{"en":"We gain a lower monthly cost with the first option, but we give up faster support.","zh":"选择第一个方案，我们可以得到较低的月费，但会牺牲比较快的支援。","patterns":["s-b1-17"]},{"en":"Instead of repeating our preferences, we started talking about the decision criteria.","zh":"我们没有继续重复自己的偏好，而是开始讨论决定标准。","patterns":[]},{"en":"I asked, \"What would make us choose the first service over the second?\"","zh":"我问：「什么条件会让我们选择第一个服务，而不是第二个？」","patterns":["s-b1-22"]},{"en":"The team agreed that reliability mattered most during the launch period.","zh":"团队同意，在上线期间可靠性最重要。","patterns":[]},{"en":"I said, \"If we can only fix one thing first, I'd prioritize reducing service interruptions.\"","zh":"我说：「如果只能先处理一件事，我会优先减少服务中断。」","patterns":["s-b1-27"]},{"en":"That gave us a clearer basis for the final choice.","zh":"这样我们就有了更清楚的决定依据。","patterns":[]},{"en":"Before we move on, are we all clear on why we're choosing the second option?","zh":"继续之前，我们都清楚为什么要选择第二个方案了吗？","patterns":["s-b1-29"]}]},{"id":"rv2-work-03","theme":"work-study","order":3,"title":"Giving Feedback Without Making It Personal","titleZh":"给反馈时不把问题变成人身批评","summary":"Raise a concern, invite correction, and keep the discussion focused on behavior and results.","patterns":[{"sentenceId":"s-b1-18","conversationId":"b1-feedback","enHint":"I want to be clear that + clause.","zhHint":"我想先说清楚……。","explanation":"Use this to set an important expectation before giving feedback."},{"sentenceId":"s-b1-19","conversationId":"b1-ask-context","enHint":"Correct me if I'm wrong, but + clause.","zhHint":"如果我理解错了请纠正我，不过……。","explanation":"Use this to present an observation while leaving room for correction."},{"sentenceId":"s-b1-26","conversationId":"b1-acknowledge-disagree","enHint":"I agree that + clause; where I differ is + clause.","zhHint":"我同意……；我们不同的地方在于……。","explanation":"Use this to separate agreement from disagreement in a calm way."},{"sentenceId":"s-b1-35","conversationId":"b1-bring-up-noise","enHint":"The reason I brought it up is that + clause.","zhHint":"我之所以提这件事，是因为……。","explanation":"Use this to explain why an issue is worth discussing."},{"sentenceId":"s-b1-12","conversationId":"b1-setting-boundary","enHint":"I don't want to overreact, but + clause.","zhHint":"我不想把事情想得太严重，不过……。","explanation":"Use this to raise a concern without exaggerating it."}],"lines":[{"en":"I needed to give a coworker feedback about a task that had been late twice.","zh":"我需要针对一个已经连续两次延迟的任务给同事反馈。","patterns":[]},{"en":"I didn't want the conversation to sound like a personal attack.","zh":"我不希望这场对话听起来像是在针对他个人。","patterns":[]},{"en":"I started by saying, \"I want to be clear that I'm talking about the process, not your effort.\"","zh":"我先说：「我想先说清楚，我谈的是流程，不是在否定你的努力。」","patterns":["s-b1-18"]},{"en":"Then I said, \"Correct me if I'm wrong, but the handoff was later than we agreed both times.\"","zh":"接着我说：「如果我理解错了请纠正我，不过这两次交接时间都比我们原本约定的晚。」","patterns":["s-b1-19"]},{"en":"He explained that another task had taken more time than expected.","zh":"他解释说另一个任务花了比预期更多的时间。","patterns":[]},{"en":"I told him, \"I agree that the extra work was real; where I differ is how early we should communicate the delay.\"","zh":"我告诉他：「我同意确实有额外工作；我们不同的地方在于应该多早沟通延迟。」","patterns":["s-b1-26"]},{"en":"The reason I brought it up is that the next team depends on receiving the file on time.","zh":"我之所以提这件事，是因为下一个团队需要准时收到档案。","patterns":["s-b1-35"]},{"en":"I added, \"I don't want to overreact, but this could create a bigger problem if we don't change the handoff process.\"","zh":"我补充：「我不想把事情想得太严重，不过如果不调整交接流程，这可能会造成更大的问题。」","patterns":["s-b1-12"]},{"en":"We agreed to send an early warning whenever a deadline looked uncertain.","zh":"我们最后同意，只要截止时间看起来可能有问题，就要提早通知。","patterns":[]},{"en":"The conversation stayed practical because we focused on the behavior that needed to change.","zh":"因为我们专注在需要改变的行为上，所以整场对话都很务实。","patterns":[]}]},{"id":"rv2-daily-04","theme":"daily-life","order":4,"title":"A Quick Grocery Stop After Work","titleZh":"下班后快速买点东西","summary":"Find what you need, check a price, and handle a small payment problem without wasting time.","patterns":[{"sentenceId":"s-a1-10","conversationId":"a1-convenience-store","enHint":"Where can I find + noun?","zhHint":"请问……在哪里？","explanation":"Use this when you know what you need but do not know where it is located."},{"sentenceId":"s-a1-16","conversationId":"a1-shopping","enHint":"How much is + noun?","zhHint":"……多少钱？","explanation":"Use this to check the price of one item directly."},{"sentenceId":"s-a1-44","conversationId":"a1-not-with-me","enHint":"I don't have + noun + with me.","zhHint":"我身上没有带……。","explanation":"Use this when something you need is not currently with you."},{"sentenceId":"s-a2-40","conversationId":"a2-happen-to-know","enHint":"Do you happen to know where + place / thing + is?","zhHint":"你刚好知道……在哪里吗？","explanation":"A softer way to ask someone for location information."},{"sentenceId":"s-b1-43","conversationId":"b1-rather-than","enHint":"I'd rather + base verb + than + base verb.","zhHint":"比起……，我宁愿……。","explanation":"Use this to show a clear preference between two actions."}],"lines":[{"en":"I stopped at a supermarket after work because I only needed a few things.","zh":"下班后我去了超市，因为我只需要买几样东西。","patterns":[]},{"en":"I asked a staff member, \"Where can I find cooking oil?\"","zh":"我问工作人员：「请问食用油在哪里？」","patterns":["s-a1-10"]},{"en":"After I found it, I picked up a small bottle and checked the label.","zh":"找到以后，我拿了一小瓶并看了一下标签。","patterns":[]},{"en":"I asked, \"How much is this one?\"","zh":"我问：「这个多少钱？」","patterns":["s-a1-16"]},{"en":"At the checkout, I realized I didn't have any cash with me.","zh":"结账的时候，我才发现身上没有带现金。","patterns":["s-a1-44"]},{"en":"My mobile payment was also taking longer than usual to connect.","zh":"我的行动支付也比平常更久才连上。","patterns":[]},{"en":"I asked, \"Do you happen to know where the nearest ATM is?\"","zh":"我问：「你刚好知道最近的 ATM 在哪里吗？」","patterns":["s-a2-40"]},{"en":"The cashier said there was one just outside the entrance.","zh":"店员说入口外面就有一台。","patterns":[]},{"en":"I'd rather get some cash than keep everyone waiting at the counter.","zh":"比起让后面的人一直等，我宁愿先去领一点现金。","patterns":["s-b1-43"]},{"en":"A few minutes later, I came back, paid, and headed home.","zh":"几分钟后，我回来付款，然后就回家了。","patterns":[]}]},{"id":"rv2-daily-05","theme":"daily-life","order":5,"title":"A Washing Machine That Won't Start","titleZh":"洗衣机突然无法启动","summary":"Describe a household problem clearly and ask the right questions before assuming the machine is broken.","patterns":[{"sentenceId":"s-a1-13","conversationId":"a1-laundry","enHint":"I need help with + noun / -ing form.","zhHint":"我需要人帮我处理……。","explanation":"Use this to clearly say what kind of help you need."},{"sentenceId":"s-a1-21","conversationId":"a1-laundry","enHint":"How long does + noun / -ing form + take?","zhHint":"……大概要多久？","explanation":"Use this to ask about the expected duration of a task or process."},{"sentenceId":"s-a2-11","conversationId":"a2-asking-help","enHint":"I'm having trouble + -ing form.","zhHint":"我在……这件事上有点困难。","explanation":"Use this when an action is difficult or not working as expected."},{"sentenceId":"s-a2-25","conversationId":"a2-building-repair","enHint":"There seems to be a problem with + noun.","zhHint":"……似乎有点问题。","explanation":"A neutral way to report a problem before the cause is known."},{"sentenceId":"s-b1-35","conversationId":"b1-bring-up-noise","enHint":"The reason I brought it up is that + clause.","zhHint":"我之所以提这件事，是因为……。","explanation":"Use this to explain why you decided a problem was worth mentioning."}],"lines":[{"en":"I put my clothes into the washing machine and pressed the start button.","zh":"我把衣服放进洗衣机，然后按下启动键。","patterns":[]},{"en":"Nothing happened, even though the display was still on.","zh":"虽然显示面板还亮着，但什么都没有发生。","patterns":[]},{"en":"I called the building office and said, \"I need help with the washing machine.\"","zh":"我打电话给管理室说：「我需要人帮我处理洗衣机的问题。」","patterns":["s-a1-13"]},{"en":"I explained, \"I'm having trouble getting it to start.\"","zh":"我解释：「我现在很难让它启动。」","patterns":["s-a2-11"]},{"en":"There seems to be a problem with the door sensor.","zh":"门的感应器似乎有点问题。","patterns":["s-a2-25"]},{"en":"The staff member asked me to open and close the door again firmly.","zh":"工作人员请我把门重新用力开关一次。","patterns":[]},{"en":"That worked, but I still wanted someone to check it later.","zh":"这样就能启动了，不过我还是希望之后有人来检查。","patterns":[]},{"en":"I asked, \"How long does a repair like this usually take?\"","zh":"我问：「这种维修通常大概要多久？」","patterns":["s-a1-21"]},{"en":"The reason I brought it up is that the same thing happened twice this week.","zh":"我之所以提这件事，是因为这个星期同样的问题已经发生两次了。","patterns":["s-b1-35"]},{"en":"They arranged for someone to inspect the machine the next afternoon.","zh":"他们安排隔天下午派人来检查洗衣机。","patterns":[]}]},{"id":"rv2-daily-06","theme":"daily-life","order":6,"title":"Borrowing a Charger at a Café","titleZh":"在咖啡店借充电器","summary":"Ask for a small favor, protect your belongings, and keep the request easy for the other person.","patterns":[{"sentenceId":"s-a1-17","conversationId":"a1-phone-charge","enHint":"Can I + base verb + here?","zhHint":"我可以在这里……吗？","explanation":"Use this to ask permission to do something in a place."},{"sentenceId":"s-a1-41","conversationId":"a1-give-minute","enHint":"Can you give me a + time word?","zhHint":"可以给我……吗？","explanation":"Use this to ask someone for a short amount of time."},{"sentenceId":"s-a2-3","conversationId":"a2-asking-help","enHint":"I was wondering if you could + base verb.","zhHint":"想问一下，你方便……吗？","explanation":"A polite way to make a request without sounding demanding."},{"sentenceId":"s-a2-32","conversationId":"a2-watch-bag","enHint":"Would you mind + -ing form?","zhHint":"你介意……吗？","explanation":"Use this for a small polite favor."},{"sentenceId":"s-b1-7","conversationId":"b1-setting-boundary","enHint":"As long as + clause, I'm fine with + noun / -ing form.","zhHint":"只要……，……我都可以。","explanation":"Use this to accept something while keeping one condition."}],"lines":[{"en":"My phone battery was almost dead while I was working in a café.","zh":"我在咖啡店工作的时候，手机电量快没了。","patterns":[]},{"en":"I saw an outlet next to an empty table and asked, \"Can I charge my phone here?\"","zh":"我看到空桌旁边有插座，就问：「我可以在这里充手机吗？」","patterns":["s-a1-17"]},{"en":"The staff said yes, but I had forgotten my charging cable.","zh":"工作人员说可以，但我忘了带充电线。","patterns":[]},{"en":"I asked, \"I was wondering if you could lend me a USB-C cable for a while.\"","zh":"我问：「想问一下，你方便借我一条 USB-C 充电线用一下吗？」","patterns":["s-a2-3"]},{"en":"They had one behind the counter and let me borrow it.","zh":"他们柜台后面刚好有一条，就借给我了。","patterns":[]},{"en":"A few minutes later, I needed to use the restroom.","zh":"几分钟后，我需要去洗手间。","patterns":[]},{"en":"I asked the person next to me, \"Would you mind watching my bag for a minute?\"","zh":"我问旁边的人：「你介意帮我看一下包包一分钟吗？」","patterns":["s-a2-32"]},{"en":"Then I added, \"Can you give me a minute? I'll be right back.\"","zh":"然后我补充：「可以给我一分钟吗？我马上回来。」","patterns":["s-a1-41"]},{"en":"He said, \"As long as you're not gone long, I'm fine with watching it.\"","zh":"他说：「只要你不要离开太久，我可以帮你看。」","patterns":["s-b1-7"]},{"en":"I came back quickly, thanked him, and returned the cable before leaving.","zh":"我很快就回来，向他道谢，并在离开前归还充电线。","patterns":[]}]},{"id":"rv2-social-04","theme":"social-communication","order":4,"title":"Saying No to a Last-Minute Invitation","titleZh":"婉拒临时邀约","summary":"Decline without overexplaining while still making your reason clear and respectful.","patterns":[{"sentenceId":"s-a1-26","conversationId":"a1-simple-reason","enHint":"I can't + base verb + because + clause.","zhHint":"我不能……，因为……。","explanation":"Use this to give a simple direct reason."},{"sentenceId":"s-a2-44","conversationId":"a2-not-in-mood","enHint":"I'm not really in the mood for + noun / -ing form.","zhHint":"我今天不太想……。","explanation":"Use this to explain your current mood honestly."},{"sentenceId":"s-b1-32","conversationId":"b1-too-tired","enHint":"It's not that + clause; it's just that + clause.","zhHint":"不是因为……；只是……。","explanation":"Use this to prevent the other person from misunderstanding your reason."},{"sentenceId":"s-b1-40","conversationId":"b1-dont-mind-as-long","enHint":"I don't mind + noun / -ing form + as long as + clause.","zhHint":"只要……，我不介意……。","explanation":"Use this to show flexibility while keeping one limit."},{"sentenceId":"s-b1-18","conversationId":"b1-decline-invitation","enHint":"I want to be clear that + clause.","zhHint":"我想先说明清楚……。","explanation":"Use this when you want to prevent your refusal from sounding personal."}],"lines":[{"en":"A friend invited me to a crowded bar less than an hour before they were leaving.","zh":"朋友在要出发前不到一个小时才邀我一起去一家很挤的酒吧。","patterns":[]},{"en":"I had already had a long day and wanted a quiet evening.","zh":"我今天已经过得很累，只想安静地度过晚上。","patterns":[]},{"en":"I said, \"I can't go tonight because I need some time to rest.\"","zh":"我说：「我今晚不能去，因为我需要一点时间休息。」","patterns":["s-a1-26"]},{"en":"I also told him, \"I'm not really in the mood for a crowded place tonight.\"","zh":"我也告诉他：「我今晚不太想去人很多的地方。」","patterns":["s-a2-44"]},{"en":"He asked whether something was wrong.","zh":"他问我是不是发生了什么事。","patterns":[]},{"en":"I explained, \"It's not that I don't want to see everyone; it's just that I'm exhausted.\"","zh":"我解释：「不是因为我不想见大家，只是我真的很累。」","patterns":["s-b1-32"]},{"en":"I told him, \"I want to be clear that I'm not avoiding you.\"","zh":"我告诉他：「我想先说明清楚，我不是在躲你。」","patterns":["s-b1-18"]},{"en":"Then I said I didn't mind meeting for coffee the next day as long as we kept it relaxed.","zh":"然后我说，只要轻松一点，我不介意隔天一起喝咖啡。","patterns":["s-b1-40"]},{"en":"He understood and told me to get some rest.","zh":"他理解了，并叫我好好休息。","patterns":[]},{"en":"Saying no clearly took less energy than inventing a long excuse.","zh":"直接说清楚拒绝，反而比编一个很长的借口省力。","patterns":[]}]},{"id":"rv2-social-05","theme":"social-communication","order":5,"title":"Asking a Friend for a Small Favor","titleZh":"请朋友帮一个小忙","summary":"Make a request without pressure and offer help in return.","patterns":[{"sentenceId":"s-a2-3","conversationId":"a2-asking-help","enHint":"I was wondering if you could + base verb.","zhHint":"想问一下，你方便……吗？","explanation":"Use this for a polite request that gives the other person room to say no."},{"sentenceId":"s-a2-32","conversationId":"a2-watch-bag","enHint":"Would you mind + -ing form?","zhHint":"你介意……吗？","explanation":"Use this to ask for a small favor politely."},{"sentenceId":"s-a1-29","conversationId":"a1-offer-help","enHint":"Do you want me to + base verb?","zhHint":"你要不要我帮你……？","explanation":"Use this to offer a simple action in return."},{"sentenceId":"s-a1-41","conversationId":"a1-give-minute","enHint":"Can you give me a + time word?","zhHint":"可以给我……吗？","explanation":"Use this to ask for a short amount of time."},{"sentenceId":"s-b1-7","conversationId":"b1-setting-boundary","enHint":"As long as + clause, I'm fine with + noun / -ing form.","zhHint":"只要……，……我都可以。","explanation":"Use this to accept a favor or arrangement while stating one condition."}],"lines":[{"en":"I needed someone to receive a small package while I was away from home.","zh":"我不在家的时候，需要有人帮我收一个小包裹。","patterns":[]},{"en":"I called a friend who lived nearby.","zh":"我打电话给住在附近的朋友。","patterns":[]},{"en":"I said, \"I was wondering if you could receive a package for me tomorrow.\"","zh":"我说：「想问一下，你方便明天帮我收一个包裹吗？」","patterns":["s-a2-3"]},{"en":"Then I asked, \"Would you mind keeping it at your place until evening?\"","zh":"然后我问：「你介意帮我放在你家到晚上吗？」","patterns":["s-a2-32"]},{"en":"He said that was fine but wanted to know the delivery window.","zh":"他说可以，不过想知道大概会几点送到。","patterns":[]},{"en":"I told him it should arrive between two and four.","zh":"我告诉他应该会在两点到四点之间送到。","patterns":[]},{"en":"He said, \"As long as it isn't too large, I'm fine with taking it.\"","zh":"他说：「只要包裹不会太大，我可以帮你收。」","patterns":["s-b1-7"]},{"en":"I replied, \"Can you give me a minute? I'll check the size in the order details.\"","zh":"我回复：「可以给我一分钟吗？我查一下订单上的尺寸。」","patterns":["s-a1-41"]},{"en":"After checking, I asked, \"Do you want me to bring you coffee when I pick it up?\"","zh":"确认以后，我问：「我去拿包裹的时候要不要顺便带咖啡给你？」","patterns":["s-a1-29"]},{"en":"He laughed and said the favor was small enough that coffee wasn't necessary.","zh":"他笑着说这个忙很小，不需要特地请咖啡。","patterns":[]}]},{"id":"rv2-social-06","theme":"social-communication","order":6,"title":"Disagreeing Without Turning It into an Argument","titleZh":"意见不同但不把对话变成争吵","summary":"Clarify meaning, acknowledge the other person's point, and isolate the real disagreement.","patterns":[{"sentenceId":"s-a1-23","conversationId":"a1-clarify-entrance","enHint":"Do you mean + noun / clause?","zhHint":"你的意思是……吗？","explanation":"Use this to check what the other person actually means."},{"sentenceId":"s-b1-3","conversationId":"b1-opinion","enHint":"I can see why + clause, but + clause.","zhHint":"我能理解为什么……，不过……。","explanation":"Use this to acknowledge a reasonable point before disagreeing."},{"sentenceId":"s-b1-26","conversationId":"b1-acknowledge-disagree","enHint":"I agree that + clause; where I differ is + clause.","zhHint":"我同意……；我们不同的地方在于……。","explanation":"Use this to separate agreement from the exact point of disagreement."},{"sentenceId":"s-b1-19","conversationId":"b1-ask-context","enHint":"Correct me if I'm wrong, but + clause.","zhHint":"如果我理解错了请纠正我，不过……。","explanation":"Use this to test your understanding before making a stronger claim."},{"sentenceId":"s-b1-29","conversationId":"b1-check-alignment","enHint":"Before we move on, are we all clear on + noun / clause?","zhHint":"继续之前，我们都清楚……了吗？","explanation":"Use this to confirm shared understanding before ending the discussion."}],"lines":[{"en":"A friend and I disagreed about whether to cancel a weekend plan because of the weather.","zh":"我和朋友对于要不要因为天气取消周末计划意见不同。","patterns":[]},{"en":"I asked, \"Do you mean you want to cancel the whole day, not just the outdoor part?\"","zh":"我问：「你的意思是想取消整天的行程，而不只是户外活动吗？」","patterns":["s-a1-23"]},{"en":"He said he didn't want to spend the day dealing with rain.","zh":"他说他不想整天都在处理下雨的问题。","patterns":[]},{"en":"I replied, \"I can see why you'd rather avoid the rain, but we still have indoor options.\"","zh":"我回复：「我能理解你为什么想避开下雨，不过我们还是有室内选择。」","patterns":["s-b1-3"]},{"en":"He agreed that an indoor plan could work.","zh":"他同意室内安排也可以。","patterns":[]},{"en":"I said, \"I agree that the original plan doesn't make sense; where I differ is whether we need to cancel everything.\"","zh":"我说：「我同意原本的计划已经不合适；我们不同的地方在于是不是需要全部取消。」","patterns":["s-b1-26"]},{"en":"Then I added, \"Correct me if I'm wrong, but it sounds like your main concern is getting stuck outside.\"","zh":"接着我补充：「如果我理解错了请纠正我，不过听起来你最担心的是被困在户外。」","patterns":["s-b1-19"]},{"en":"He said that was exactly what he meant.","zh":"他说那正是他的意思。","patterns":[]},{"en":"We replaced the hike with a museum and kept the dinner reservation.","zh":"我们把健行改成博物馆，并保留晚餐预约。","patterns":[]},{"en":"Before we move on, are we all clear on the new plan?","zh":"继续之前，我们都清楚新的安排了吗？","patterns":["s-b1-29"]}]},{"id":"rv2-food-04","theme":"food-shopping","order":4,"title":"Returning a Jacket That Doesn't Fit","titleZh":"退掉尺寸不合的外套","summary":"Explain what is wrong, ask about another size, and state whether you want an exchange or refund.","patterns":[{"sentenceId":"s-a1-7","conversationId":"a1-shopping","enHint":"Do you have this in + size / color?","zhHint":"这个有……的吗？","explanation":"Use this to ask whether the same item is available in another version."},{"sentenceId":"s-a1-39","conversationId":"a1-other-size","enHint":"Do you have this in a different + size / color?","zhHint":"这个有别的……吗？","explanation":"Use this when you want a different version of the same item."},{"sentenceId":"s-a2-25","conversationId":"a2-soft-problem","enHint":"There seems to be a problem with + noun.","zhHint":"……似乎有点问题。","explanation":"Use this to describe an issue without sounding accusatory."},{"sentenceId":"s-a2-30","conversationId":"a2-needed-result","enHint":"What I need is + noun, not + noun.","zhHint":"我需要的是……，不是……。","explanation":"Use this to clearly state the result you want."},{"sentenceId":"s-b1-42","conversationId":"b1-what-bothers-me","enHint":"What bothers me most is not + noun / clause; it's + noun / clause.","zhHint":"最让我介意的不是……，而是……。","explanation":"Use this to explain what part of the problem actually matters."}],"lines":[{"en":"I ordered a jacket online, but it was much larger than I expected.","zh":"我在线上订了一件外套，但收到以后比预期大很多。","patterns":[]},{"en":"I took it to the store with the receipt and original tags.","zh":"我带着收据和原本的吊牌去店里。","patterns":[]},{"en":"I asked, \"Do you have this in medium?\"","zh":"我问：「这个有 M 号的吗？」","patterns":["s-a1-7"]},{"en":"The staff checked and said medium was sold out.","zh":"店员查了一下，说 M 号已经卖完。","patterns":[]},{"en":"I asked, \"Do you have this in a different size at another branch?\"","zh":"我问：「其他分店有这个不同尺寸的吗？」","patterns":["s-a1-39"]},{"en":"There seems to be a problem with the online size guide because this fits much looser than the measurements suggested.","zh":"线上尺寸表似乎有点问题，因为实际穿起来比标示的尺寸宽松很多。","patterns":["s-a2-25"]},{"en":"The staff offered store credit.","zh":"店员提出可以改成店内购物金。","patterns":[]},{"en":"I said, \"What I need is a refund, not store credit.\"","zh":"我说：「我需要的是退款，不是购物金。」","patterns":["s-a2-30"]},{"en":"What bothers me most is not the wrong size; it's being unable to tell which size to order next time.","zh":"最让我介意的不是尺寸不对，而是下次还是不知道该订哪个尺寸。","patterns":["s-b1-42"]},{"en":"They processed the refund and suggested trying the item in person before ordering again.","zh":"他们处理了退款，并建议我下次订购以前先到现场试穿。","patterns":[]}]},{"id":"rv2-food-05","theme":"food-shopping","order":5,"title":"A Cash-Only Café","titleZh":"只收现金的咖啡店","summary":"Handle a payment surprise quickly without holding up the line.","patterns":[{"sentenceId":"s-a1-32","conversationId":"a1-payment-method","enHint":"Do you take + payment method?","zhHint":"你们收……吗？","explanation":"Use this to check whether a business accepts a payment method."},{"sentenceId":"s-a1-44","conversationId":"a1-not-with-me","enHint":"I don't have + noun + with me.","zhHint":"我身上没有带……。","explanation":"Use this when something required is not currently with you."},{"sentenceId":"s-a1-41","conversationId":"a1-give-minute","enHint":"Can you give me a + time word?","zhHint":"可以给我……吗？","explanation":"Use this to ask for a brief amount of time."},{"sentenceId":"s-a2-40","conversationId":"a2-happen-to-know","enHint":"Do you happen to know where + place + is?","zhHint":"你刚好知道……在哪里吗？","explanation":"Use this to politely ask for a nearby location."},{"sentenceId":"s-a2-22","conversationId":"a2-backup-plan","enHint":"If that doesn't work, we can + base verb.","zhHint":"如果那样不行，我们可以……。","explanation":"Use this to offer a backup solution."}],"lines":[{"en":"I stopped at a small café and ordered a drink before meeting a friend.","zh":"我在和朋友见面以前，先到一家小咖啡店点饮料。","patterns":[]},{"en":"At the counter, I asked, \"Do you take credit cards?\"","zh":"在柜台，我问：「你们收信用卡吗？」","patterns":["s-a1-32"]},{"en":"The cashier said the shop was cash only.","zh":"店员说这家店只收现金。","patterns":[]},{"en":"I realized I didn't have enough cash with me.","zh":"我才发现身上的现金不够。","patterns":["s-a1-44"]},{"en":"There were several people waiting behind me.","zh":"我后面还有好几个人在排队。","patterns":[]},{"en":"I said, \"Can you give me a minute? I'll see if I can get cash nearby.\"","zh":"我说：「可以给我一分钟吗？我看看附近能不能领现金。」","patterns":["s-a1-41"]},{"en":"Then I asked, \"Do you happen to know where the nearest ATM is?\"","zh":"然后我问：「你刚好知道最近的 ATM 在哪里吗？」","patterns":["s-a2-40"]},{"en":"The cashier pointed to a convenience store across the street.","zh":"店员指向马路对面的一家便利商店。","patterns":[]},{"en":"My friend said, \"If that doesn't work, we can just go to another café.\"","zh":"我朋友说：「如果那样不行，我们可以直接去另一家咖啡店。」","patterns":["s-a2-22"]},{"en":"I found the ATM quickly and came back before my order was ready.","zh":"我很快找到 ATM，并在饮料做好以前就回来了。","patterns":[]}]},{"id":"rv2-food-06","theme":"food-shopping","order":6,"title":"Choosing Between Two Backpacks","titleZh":"在两个背包之间做选择","summary":"Compare two products using the features that actually matter instead of only looking at price.","patterns":[{"sentenceId":"s-a1-27","conversationId":"a1-choose-option","enHint":"Which + noun + should I choose?","zhHint":"我应该选哪个……？","explanation":"Use this to ask directly for help choosing one option."},{"sentenceId":"s-a2-26","conversationId":"a2-compare-options","enHint":"Option A + is more + adjective, while + option B + is more + adjective.","zhHint":"……比较……，而……比较……。","explanation":"Use this to compare two options on different qualities."},{"sentenceId":"s-a2-33","conversationId":"a2-train-or-bus","enHint":"I'm trying to decide between + option A + and + option B.","zhHint":"我正在考虑要选……还是……。","explanation":"Use this when you have narrowed your decision to two choices."},{"sentenceId":"s-b1-45","conversationId":"b1-can-see-why","enHint":"I get why + clause, but + clause.","zhHint":"我懂为什么……，不过……。","explanation":"Use this to acknowledge another person's reasoning while keeping your own view."},{"sentenceId":"s-b1-46","conversationId":"b1-comes-down-to","enHint":"If it comes down to + A + or + B, I'd choose + choice.","zhHint":"如果最后要在……和……之间选，我会选……。","explanation":"Use this when you want to identify the deciding priority."}],"lines":[{"en":"I needed a new backpack for work and short trips.","zh":"我需要一个新的背包，用来上班和短途旅行。","patterns":[]},{"en":"I found two models that both looked good.","zh":"我找到两个看起来都不错的款式。","patterns":[]},{"en":"I asked my friend, \"Which one should I choose?\"","zh":"我问朋友：「我应该选哪个？」","patterns":["s-a1-27"]},{"en":"I'm trying to decide between the lighter one and the larger one.","zh":"我正在考虑要选比较轻的，还是比较大的。","patterns":["s-a2-33"]},{"en":"The first backpack is more comfortable, while the second one is more spacious.","zh":"第一个背包比较舒服，而第二个空间比较大。","patterns":["s-a2-26"]},{"en":"My friend liked the larger one because it could carry more things.","zh":"我朋友喜欢比较大的，因为可以装更多东西。","patterns":[]},{"en":"I told him, \"I get why you prefer the extra space, but I carry the bag every day.\"","zh":"我告诉他：「我懂为什么你比较喜欢额外空间，不过我每天都要背这个包。」","patterns":["s-b1-45"]},{"en":"The larger model was also a little heavier even when empty.","zh":"比较大的款式即使空着也比较重。","patterns":[]},{"en":"If it comes down to comfort or extra space, I'd choose comfort.","zh":"如果最后要在舒适度和额外空间之间选，我会选舒适度。","patterns":["s-b1-46"]},{"en":"I bought the lighter backpack because it matched how I would actually use it.","zh":"最后我买了比较轻的背包，因为它更符合我实际的使用方式。","patterns":[]}]},{"id":"rv2-travel-04","theme":"travel-transport","order":4,"title":"Finding Your Way in an Unfamiliar City","titleZh":"在陌生城市找路","summary":"Ask for directions naturally and adjust the route when the easiest option is not obvious.","patterns":[{"sentenceId":"s-a1-10","conversationId":"a1-find-pharmacy","enHint":"Where can I find + place / thing?","zhHint":"请问……在哪里？","explanation":"Use this when searching for a place or service."},{"sentenceId":"s-a1-31","conversationId":"a1-find-pharmacy","enHint":"Is there a + place + nearby?","zhHint":"附近有……吗？","explanation":"Use this to check whether something you need is close."},{"sentenceId":"s-a2-40","conversationId":"a2-happen-to-know","enHint":"Do you happen to know where + place + is?","zhHint":"你刚好知道……在哪里吗？","explanation":"A softer direction question for asking a stranger."},{"sentenceId":"s-a2-38","conversationId":"a2-book-online","enHint":"It would be easier if we + past-tense verb.","zhHint":"如果我们……，会比较容易。","explanation":"Use this to suggest a simpler route or method."},{"sentenceId":"s-b1-39","conversationId":"b1-under-impression","enHint":"I was under the impression that + clause.","zhHint":"我原本以为……。","explanation":"Use this to explain an expectation that turned out to be inaccurate."}],"lines":[{"en":"It was my first afternoon in the city, and I wanted to walk to an old market.","zh":"这是我到这座城市的第一个下午，我想走路去一个老市场。","patterns":[]},{"en":"The map on my phone kept sending me toward a street that was closed.","zh":"手机地图一直叫我往一条封闭的街道走。","patterns":[]},{"en":"I asked someone, \"Where can I find the entrance to the market?\"","zh":"我问路人：「请问市场入口在哪里？」","patterns":["s-a1-10"]},{"en":"Then I asked, \"Is there a metro station nearby?\"","zh":"然后我问：「附近有捷运站吗？」","patterns":["s-a1-31"]},{"en":"He pointed down the street but said the walking route was a little confusing.","zh":"他指向街道另一边，不过说步行路线有一点复杂。","patterns":[]},{"en":"I asked, \"Do you happen to know where the nearest station entrance is?\"","zh":"我问：「你刚好知道最近的捷运入口在哪里吗？」","patterns":["s-a2-40"]},{"en":"He showed me a simpler route through a public square.","zh":"他告诉我一条经过广场的简单路线。","patterns":[]},{"en":"I told my friend, \"It would be easier if we took the metro for one stop.\"","zh":"我告诉朋友：「如果我们搭一站捷运，会比较容易。」","patterns":["s-a2-38"]},{"en":"I was under the impression that the market was only a five-minute walk from our hotel.","zh":"我原本以为市场离饭店只有五分钟路程。","patterns":["s-b1-39"]},{"en":"Once we stopped relying only on the map, getting there was much easier.","zh":"我们不再只依赖地图以后，要到那里反而简单多了。","patterns":[]}]},{"id":"rv2-travel-05","theme":"travel-transport","order":5,"title":"A Delayed Train and a Backup Route","titleZh":"火车延误与备用路线","summary":"Notice a delay, explain its effect, and keep the trip moving with a backup plan.","patterns":[{"sentenceId":"s-a2-36","conversationId":"a2-flight-delay","enHint":"It looks like + subject + has / have been + past participle.","zhHint":"看起来……已经被……了。","explanation":"Use this when visible information suggests that something has changed."},{"sentenceId":"s-a2-16","conversationId":"a2-late-arrival","enHint":"I got delayed because + clause.","zhHint":"我因为……耽误了一下。","explanation":"Use this to explain why your timing changed."},{"sentenceId":"s-a2-22","conversationId":"a2-backup-plan","enHint":"If that doesn't work, we can + base verb.","zhHint":"如果那样不行，我们可以……。","explanation":"Use this to offer a second option."},{"sentenceId":"s-a2-27","conversationId":"a2-backup-plan","enHint":"In case + clause, we could + base verb.","zhHint":"万一……，我们可以……。","explanation":"Use this to prepare a backup before a possible problem happens."},{"sentenceId":"s-b1-34","conversationId":"b1-rain-trip","enHint":"Even if + clause, I'd still + base verb.","zhHint":"即使……，我还是会……。","explanation":"Use this to keep the main goal despite a problem."}],"lines":[{"en":"We were taking a train to another city for a day trip.","zh":"我们要搭火车去另一个城市一日游。","patterns":[]},{"en":"When we reached the platform, there was no train and everyone was checking the screen.","zh":"我们到月台时没有看到火车，所有人都在看屏幕。","patterns":[]},{"en":"It looks like our train has been delayed.","zh":"看起来我们的火车已经延误了。","patterns":["s-a2-36"]},{"en":"The new departure time was almost forty minutes later.","zh":"新的出发时间晚了将近四十分钟。","patterns":[]},{"en":"I messaged the person waiting for us and said, \"I got delayed because our train is running late.\"","zh":"我传讯息给等我们的人说：「我因为火车延误而耽误了一下。」","patterns":["s-a2-16"]},{"en":"My friend checked whether another train would leave sooner.","zh":"我朋友查了一下有没有其他班次会更早出发。","patterns":[]},{"en":"I said, \"If that doesn't work, we can take the express bus.\"","zh":"我说：「如果那样不行，我们可以搭快速巴士。」","patterns":["s-a2-22"]},{"en":"In case the delay gets longer, we could also move lunch to a later time.","zh":"万一延误变得更久，我们也可以把午餐改晚一点。","patterns":["s-a2-27"]},{"en":"Even if we arrive an hour late, I'd still like to make the trip.","zh":"即使我们晚一个小时到，我还是想继续这趟旅行。","patterns":["s-b1-34"]},{"en":"We eventually stayed with the original train because the delay stopped increasing.","zh":"最后我们还是搭原本那班火车，因为延误时间没有继续增加。","patterns":[]}]},{"id":"rv2-travel-06","theme":"travel-transport","order":6,"title":"Using a Station Locker Before Your Train","titleZh":"搭车前使用车站寄物柜","summary":"Store luggage, check the rules, and avoid carrying bags around while waiting for a train.","patterns":[{"sentenceId":"s-a1-19","conversationId":"a1-using-locker","enHint":"Is this the right place for + noun / -ing form?","zhHint":"这里是办理……的地方吗？","explanation":"Use this to confirm that you are at the correct place."},{"sentenceId":"s-a1-21","conversationId":"a1-using-locker","enHint":"How long does + noun / -ing form + take?","zhHint":"……大概要多久？","explanation":"Use this to ask about the duration of a process."},{"sentenceId":"s-a2-18","conversationId":"a2-rental-rules","enHint":"Do I need to + base verb + before + noun / -ing form?","zhHint":"在……以前，我需要先……吗？","explanation":"Use this to check a requirement."},{"sentenceId":"s-a2-40","conversationId":"a2-happen-to-know","enHint":"Do you happen to know where + place / thing + is?","zhHint":"你刚好知道……在哪里吗？","explanation":"Use this to politely ask for a location."},{"sentenceId":"s-b1-16","conversationId":"b1-under-impression","enHint":"Based on what we know so far, + clause.","zhHint":"根据目前知道的资讯，……。","explanation":"Use this to summarize the practical conclusion from available information."}],"lines":[{"en":"We had almost two hours before our train and didn't want to carry our luggage around.","zh":"距离火车出发还有将近两个小时，我们不想一直提着行李。","patterns":[]},{"en":"We found a row of lockers near the station entrance.","zh":"我们在车站入口附近找到一排寄物柜。","patterns":[]},{"en":"I asked, \"Is this the right place for storing large bags?\"","zh":"我问：「这里是寄放大型行李的地方吗？」","patterns":["s-a1-19"]},{"en":"A staff member said the larger lockers were on the other side of the hall.","zh":"工作人员说大型寄物柜在大厅另一边。","patterns":[]},{"en":"I asked, \"Do you happen to know where the payment machine is?\"","zh":"我问：「你刚好知道付款机在哪里吗？」","patterns":["s-a2-40"]},{"en":"He pointed to a machine next to the lockers.","zh":"他指向寄物柜旁边的一台机器。","patterns":[]},{"en":"I asked, \"Do I need to keep the receipt before opening the locker again?\"","zh":"我问：「再次打开寄物柜以前，我需要保留收据吗？」","patterns":["s-a2-18"]},{"en":"Then I asked, \"How long does the locker stay active after I pay?\"","zh":"然后我问：「付款以后，寄物柜可以使用多久？」","patterns":["s-a1-21"]},{"en":"Based on what we know so far, we can leave the bags there until after dinner.","zh":"根据目前知道的资讯，我们可以把行李放在那里直到吃完晚餐。","patterns":["s-b1-16"]},{"en":"Once the bags were stored, we could walk around the station area comfortably.","zh":"把行李寄放好以后，我们就可以轻松地在车站附近逛逛。","patterns":[]}]},{"id":"rv2-plans-04","theme":"plans-time","order":4,"title":"Helping a Friend Until a Certain Time","titleZh":"只能帮朋友到某个时间","summary":"Agree to help while making your available time and backup plan clear.","patterns":[{"sentenceId":"s-a1-24","conversationId":"a1-wait-five-minutes","enHint":"Can you wait for + amount of time / person?","zhHint":"你可以等……吗？","explanation":"Use this to ask someone to wait."},{"sentenceId":"s-a2-28","conversationId":"a2-time-limit","enHint":"I can + base verb + until + time.","zhHint":"我可以……到……。","explanation":"Use this to state a clear time limit."},{"sentenceId":"s-a1-30","conversationId":"a1-arrival-followup","enHint":"I'll + base verb + when I get there.","zhHint":"我到了以后会……。","explanation":"Use this to promise an action after you arrive."},{"sentenceId":"s-a2-22","conversationId":"a2-backup-plan","enHint":"If that doesn't work, we can + base verb.","zhHint":"如果那样不行，我们可以……。","explanation":"Use this to offer a backup option."},{"sentenceId":"s-b1-24","conversationId":"b1-conditional-agreement","enHint":"I'm open to + noun / -ing form, provided that + clause.","zhHint":"只要……，我可以接受……。","explanation":"Use this to agree while keeping one condition."}],"lines":[{"en":"A friend asked me to help move some furniture on Saturday.","zh":"朋友请我星期六帮忙搬一些家具。","patterns":[]},{"en":"I wanted to help, but I already had another plan in the evening.","zh":"我想帮忙，不过晚上已经有别的安排。","patterns":[]},{"en":"I told him, \"I can help until four.\"","zh":"我告诉他：「我可以帮忙到四点。」","patterns":["s-a2-28"]},{"en":"He said most of the heavy work should be finished before then.","zh":"他说大部分比较重的工作应该会在那之前完成。","patterns":[]},{"en":"On Saturday morning, I messaged him, \"Can you wait for ten minutes? I'm almost there.\"","zh":"星期六早上，我传讯息给他说：「你可以等我十分钟吗？我快到了。」","patterns":["s-a1-24"]},{"en":"Then I said, \"I'll call you when I get there.\"","zh":"然后我说：「我到了以后会打给你。」","patterns":["s-a1-30"]},{"en":"He told me one more person might arrive late.","zh":"他说另外一个人可能会晚一点到。","patterns":[]},{"en":"I said, \"If that doesn't work, we can move the smaller things first.\"","zh":"我说：「如果那样不行，我们可以先搬比较小的东西。」","patterns":["s-a2-22"]},{"en":"I added, \"I'm open to staying a little longer, provided that I can still leave before five.\"","zh":"我补充：「只要我还是能在五点以前离开，我可以接受多留一下。」","patterns":["s-b1-24"]},{"en":"Because the limit was clear from the beginning, nobody expected me to stay all day.","zh":"因为一开始就把时间限制讲清楚，所以没有人预期我要待一整天。","patterns":[]}]},{"id":"rv2-plans-05","theme":"plans-time","order":5,"title":"Coordinating a Ride Home","titleZh":"协调一起搭车回家","summary":"Coordinate where to meet, handle a late arrival, and keep a backup option ready.","patterns":[{"sentenceId":"s-a1-25","conversationId":"a1-on-the-way","enHint":"I'm on my way to + place.","zhHint":"我正在去……的路上。","explanation":"Use this to update someone while traveling to the meeting point."},{"sentenceId":"s-a1-38","conversationId":"a1-meet-station","enHint":"I'll meet you in front of + place.","zhHint":"我会在……前面跟你会合。","explanation":"Use this to set a specific meeting location."},{"sentenceId":"s-a2-41","conversationId":"a2-running-late","enHint":"I'm running a little late, but + clause.","zhHint":"我会晚一点，不过……。","explanation":"Use this to give a late-arrival update and reassurance."},{"sentenceId":"s-a2-22","conversationId":"a2-backup-plan","enHint":"If that doesn't work, we can + base verb.","zhHint":"如果那样不行，我们可以……。","explanation":"Use this to offer another plan."},{"sentenceId":"s-b1-40","conversationId":"b1-dont-mind-as-long","enHint":"I don't mind + noun / -ing form + as long as + clause.","zhHint":"只要……，我不介意……。","explanation":"Use this to accept an arrangement with one condition."}],"lines":[{"en":"Three of us planned to share a ride home after an event.","zh":"活动结束后，我们三个人打算一起搭车回家。","patterns":[]},{"en":"We agreed to meet near the main entrance at ten.","zh":"我们约好十点在正门附近会合。","patterns":[]},{"en":"I texted, \"I'm on my way to the entrance now.\"","zh":"我传讯息说：「我现在正在去入口的路上。」","patterns":["s-a1-25"]},{"en":"One friend replied, \"I'm running a little late, but I should be there in ten minutes.\"","zh":"一个朋友回复：「我会晚一点，不过应该十分钟内会到。」","patterns":["s-a2-41"]},{"en":"I told everyone, \"I'll meet you in front of the ticket office.\"","zh":"我告诉大家：「我会在售票处前面跟你们会合。」","patterns":["s-a1-38"]},{"en":"The driver said he could only wait for a short time.","zh":"司机说他只能等一小段时间。","patterns":[]},{"en":"I said, \"If that doesn't work, we can call another car.\"","zh":"我说：「如果那样不行，我们可以再叫一台车。」","patterns":["s-a2-22"]},{"en":"The late friend arrived just before the driver wanted to leave.","zh":"迟到的朋友刚好在司机准备离开前赶到。","patterns":[]},{"en":"I told them, \"I don't mind waiting as long as we keep the driver updated.\"","zh":"我告诉他们：「只要我们有持续跟司机更新，我不介意等。」","patterns":["s-b1-40"]},{"en":"We all got into the car together without anyone needing to arrange a separate ride.","zh":"最后大家一起上车，没有人需要另外安排交通。","patterns":[]}]},{"id":"rv2-plans-06","theme":"plans-time","order":6,"title":"A Schedule Conflict Between Two Commitments","titleZh":"两个安排撞在一起","summary":"Define the time you can offer, compare alternatives, and confirm the final arrangement.","patterns":[{"sentenceId":"s-a2-10","conversationId":"a2-change-shift","enHint":"I'm supposed to + base verb, but + clause.","zhHint":"我本来应该要……，不过……。","explanation":"Use this when a responsibility conflicts with reality."},{"sentenceId":"s-a2-28","conversationId":"a2-time-limit","enHint":"I can + base verb + until + time.","zhHint":"我可以……到……。","explanation":"Use this to give a clear availability limit."},{"sentenceId":"s-a2-37","conversationId":"a2-friday-saturday","enHint":"Either + option A + or + option B + works for me.","zhHint":"……或……我都可以。","explanation":"Use this when two alternatives are both acceptable."},{"sentenceId":"s-b1-24","conversationId":"b1-conditional-agreement","enHint":"I'm open to + noun / -ing form, provided that + clause.","zhHint":"只要……，我可以接受……。","explanation":"Use this to agree conditionally."},{"sentenceId":"s-b1-29","conversationId":"b1-check-alignment","enHint":"Before we move on, are we all clear on + noun / clause?","zhHint":"继续之前，我们都清楚……了吗？","explanation":"Use this to confirm the final shared understanding."}],"lines":[{"en":"I noticed that a work task and a family plan had ended up on the same afternoon.","zh":"我发现一个工作任务和家庭安排刚好排在同一个下午。","patterns":[]},{"en":"I'm supposed to help at work, but I also promised to meet my family later.","zh":"我本来应该在公司帮忙，不过我也答应晚一点要和家人见面。","patterns":["s-a2-10"]},{"en":"I told my coworker, \"I can stay until four thirty.\"","zh":"我告诉同事：「我可以留到四点半。」","patterns":["s-a2-28"]},{"en":"He said the task could either start earlier or continue the next morning.","zh":"他说这个任务可以提早开始，或隔天早上再继续。","patterns":[]},{"en":"I replied, \"Either starting earlier or finishing tomorrow works for me.\"","zh":"我回复：「提早开始或明天再完成，我都可以。」","patterns":["s-a2-37"]},{"en":"The team preferred to start earlier so the urgent part could be finished that day.","zh":"团队比较希望提早开始，这样紧急的部分当天就能完成。","patterns":[]},{"en":"I said, \"I'm open to starting earlier, provided that I can leave on time.\"","zh":"我说：「只要我可以准时离开，我可以接受提早开始。」","patterns":["s-b1-24"]},{"en":"We moved the internal meeting forward by one hour.","zh":"我们把内部会议提早了一个小时。","patterns":[]},{"en":"Before we move on, are we all clear on what has to be finished before I leave?","zh":"继续之前，我们都清楚我离开前必须完成哪些事情了吗？","patterns":["s-b1-29"]},{"en":"Once the priorities were clear, both commitments fit into the day.","zh":"优先事项讲清楚以后，两个安排都能放进当天的行程。","patterns":[]}]},{"id":"rv2-work-04","theme":"work-study","order":4,"title":"Asking for More Time on a Task","titleZh":"为任务争取更多时间","summary":"Explain why a deadline is at risk and ask for time before the problem becomes urgent.","patterns":[{"sentenceId":"s-a2-10","conversationId":"a2-change-shift","enHint":"I'm supposed to + base verb, but + clause.","zhHint":"我本来应该要……，不过……。","explanation":"Use this to explain a conflict between the expected plan and current reality."},{"sentenceId":"s-a2-21","conversationId":"b1-follow-up","enHint":"Have you had a chance to + base verb + yet?","zhHint":"你已经有时间……了吗？","explanation":"Use this to check progress without demanding an immediate answer."},{"sentenceId":"s-b1-13","conversationId":"b1-more-time","enHint":"The sooner + clause, the easier it will be to + base verb.","zhHint":"越早……，之后要……就越容易。","explanation":"Use this to explain why an early decision or update matters."},{"sentenceId":"s-b1-18","conversationId":"b1-more-time","enHint":"I want to be clear that + clause.","zhHint":"我想先说明清楚……。","explanation":"Use this to set an expectation before requesting more time."},{"sentenceId":"s-b1-30","conversationId":"b1-next-action","enHint":"The next step is to + base verb + so that + clause.","zhHint":"下一步是……，这样……。","explanation":"Use this to define the next concrete action."}],"lines":[{"en":"I was working on a task that was due at the end of the day.","zh":"我正在处理一个当天结束前要完成的任务。","patterns":[]},{"en":"I'm supposed to finish it today, but I still need information from another team.","zh":"我本来应该今天完成，不过我还需要另一个团队提供资讯。","patterns":["s-a2-10"]},{"en":"I sent them a message asking, \"Have you had a chance to check the numbers yet?\"","zh":"我传讯息问他们：「你们已经有时间确认那些数字了吗？」","patterns":["s-a2-21"]},{"en":"They said they were still waiting for one source file.","zh":"他们说还在等一个来源档案。","patterns":[]},{"en":"I told my manager, \"I want to be clear that I may need until tomorrow morning.\"","zh":"我告诉主管：「我想先说明清楚，我可能需要做到明天早上。」","patterns":["s-b1-18"]},{"en":"I didn't want to wait until the deadline had already passed.","zh":"我不想等到截止时间已经过了才说。","patterns":[]},{"en":"The sooner we confirm the missing data, the easier it will be to finish the final version.","zh":"越早确认缺少的资料，之后要完成最终版本就越容易。","patterns":["s-b1-13"]},{"en":"My manager agreed that accuracy mattered more than forcing the task through that evening.","zh":"主管同意，与其硬赶当天完成，正确性更重要。","patterns":[]},{"en":"The next step is to get the source file so that I can verify the last section.","zh":"下一步是拿到来源档案，这样我就能确认最后一个部分。","patterns":["s-b1-30"]},{"en":"Because I raised the issue early, the extra time was easy to plan around.","zh":"因为我很早就提出问题，所以多出来的时间很好安排。","patterns":[]}]},{"id":"rv2-work-05","theme":"work-study","order":5,"title":"A Technical Problem That Comes and Goes","titleZh":"时好时坏的技术问题","summary":"Describe an intermittent problem using observations instead of guessing at the cause.","patterns":[{"sentenceId":"s-a2-11","conversationId":"a2-asking-help","enHint":"I'm having trouble + -ing form.","zhHint":"我在……这件事上有点困难。","explanation":"Use this to describe a task or process that is not working smoothly."},{"sentenceId":"s-a2-25","conversationId":"a2-soft-problem","enHint":"There seems to be a problem with + noun.","zhHint":"……似乎有点问题。","explanation":"Use this to report a problem without claiming you know the exact cause."},{"sentenceId":"s-b1-6","conversationId":"b1-intermittent-tech","enHint":"One thing I've noticed is + clause.","zhHint":"我注意到一件事，就是……。","explanation":"Use this to introduce an observation that may help explain a pattern."},{"sentenceId":"s-b1-16","conversationId":"b1-flag-uncertainty","enHint":"Based on what we know so far, + clause.","zhHint":"根据目前知道的资讯，……。","explanation":"Use this to make a careful conclusion from limited evidence."},{"sentenceId":"s-b1-30","conversationId":"b1-next-action","enHint":"The next step is to + base verb + so that + clause.","zhHint":"下一步是……，这样……。","explanation":"Use this to define a useful troubleshooting action."}],"lines":[{"en":"My laptop had a connection problem that was difficult to reproduce.","zh":"我的笔记型电脑出现一个很难重现的连线问题。","patterns":[]},{"en":"I'm having trouble staying connected after switching between networks.","zh":"我在切换网络以后，很难维持稳定连线。","patterns":["s-a2-11"]},{"en":"There seems to be a problem with the connection after the switch.","zh":"切换以后，连线似乎有点问题。","patterns":["s-a2-25"]},{"en":"Most of the time, everything works normally.","zh":"大部分时间一切都很正常。","patterns":[]},{"en":"One thing I've noticed is that the issue happens more often after the laptop wakes from sleep.","zh":"我注意到一件事，就是电脑从睡眠模式恢复以后更容易发生这个问题。","patterns":["s-b1-6"]},{"en":"Restarting the connection usually fixes it for a while.","zh":"重新启动连线通常可以暂时解决。","patterns":[]},{"en":"Based on what we know so far, the problem may be related to switching networks rather than the internet service itself.","zh":"根据目前知道的资讯，问题可能和切换网络有关，而不是网路服务本身。","patterns":["s-b1-16"]},{"en":"I started writing down the time and network each time it happened.","zh":"每次发生时，我开始记录时间和当时使用的网络。","patterns":[]},{"en":"The next step is to capture the error message so that technical support can compare the cases.","zh":"下一步是把错误讯息记录下来，这样技术支援人员就能比较这些情况。","patterns":["s-b1-30"]},{"en":"That gives us evidence to work with instead of guessing randomly.","zh":"这样我们就有实际资讯可以判断，而不是随便猜原因。","patterns":[]}]},{"id":"rv2-work-06","theme":"work-study","order":6,"title":"Building a Study Habit That Actually Lasts","titleZh":"建立真的能维持的学习习惯","summary":"Make a learning routine sustainable by adjusting difficulty, time, and expectations.","patterns":[{"sentenceId":"s-a2-1","conversationId":"b1-new-habit","enHint":"I've been trying to + base verb + lately.","zhHint":"我最近一直在努力……。","explanation":"Use this to describe an ongoing recent effort."},{"sentenceId":"s-a2-6","conversationId":"a2-join-class","enHint":"I'm not used to + noun / -ing form + yet.","zhHint":"我还不太习惯……。","explanation":"Use this when something is still unfamiliar but you are adapting."},{"sentenceId":"s-a2-7","conversationId":"a2-changing-plans","enHint":"If I have time, I'll + base verb.","zhHint":"如果有时间，我会……。","explanation":"Use this for an optional plan depending on available time."},{"sentenceId":"s-b1-44","conversationId":"b1-get-into-habit","enHint":"I'm trying to get into the habit of + -ing form.","zhHint":"我正在试着养成……的习惯。","explanation":"Use this when you want an action to become automatic through repetition."},{"sentenceId":"s-b1-6","conversationId":"b1-new-habit","enHint":"One thing I've noticed is + clause.","zhHint":"我注意到一件事，就是……。","explanation":"Use this to describe a pattern you have observed about your own behavior."}],"lines":[{"en":"I've been trying to study English for a short time every day lately.","zh":"我最近一直在努力每天花一点时间学英文。","patterns":["s-a2-1"]},{"en":"At first, I tried to do too much in one session.","zh":"一开始，我每次都想做太多内容。","patterns":[]},{"en":"I'm not used to studying for a long time after work yet.","zh":"我还不太习惯下班后长时间学习。","patterns":["s-a2-6"]},{"en":"So I made the daily session shorter and more specific.","zh":"所以我把每天的学习时间变短，也把目标变得更明确。","patterns":[]},{"en":"I'm trying to get into the habit of reviewing a few sentence patterns before I start reading.","zh":"我正在试着养成阅读以前先复习几个句型的习惯。","patterns":["s-b1-44"]},{"en":"If I have time, I'll add ten minutes of speaking practice.","zh":"如果有时间，我会再加十分钟口说练习。","patterns":["s-a2-7"]},{"en":"But I don't treat the extra practice as a requirement every day.","zh":"不过我不会把额外练习当成每天一定要做的要求。","patterns":[]},{"en":"One thing I've noticed is that shorter sessions are easier to repeat consistently.","zh":"我注意到一件事，就是比较短的学习时段更容易稳定重复。","patterns":["s-b1-6"]},{"en":"That matters more to me than having one very productive day and then stopping for three days.","zh":"对我来说，这比某一天学很多、接着三天都没学更重要。","patterns":[]},{"en":"The goal is to make the routine normal enough that starting no longer feels difficult.","zh":"目标是让这个习惯变得够日常，让开始学习不再觉得困难。","patterns":[]}]}],"history":{"label":"Historical Materials","labelZh":"历史教材","description":"Browse the original Single Sentence, Conversation, and Translation materials from previous months."}};
